('fy000000001', 1, '桂枝汤', '10001', '伤寒金匮・(宋版)', '1', '桂枝,芍药,甘草,生姜,大枣', replace(replace(replace('1、$f{桂枝汤} 5味@@NL@@$u{桂枝}$w{三两。去皮}    $u{芍药}$w{三两}    $u{甘草}$w{二两。炙}    $u{生姜}$w{三两。切}    $u{大枣}$w{十二枚。擘}@@NL@@@@TB@@上五味。㕮咀三味。以水七升。微火煮取三升。去滓。适寒温。服一升。服已。须臾啜热稀粥一升余。以助药力。温覆令一时许。遍身漐漐。微似有汗者益佳。不可令如水流漓。病必不除。若一服汗出病差。停后服。不必尽剂。若不汗。更服依前法。又不汗。后服小促其间。半日许。令三服尽。若病重者。一日一夜服。周时观之。服一剂尽。病证犹在者。更作服。若汗不出。乃服至二三剂。禁生冷粘滑肉面五辛酒酪臭恶等物。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 1, '600025450844229', '7B37D4BA2D23C597FD0433082583358A', '2024-09-17 08:59:43', '2024-09-17 08:59:43'),
('fy000000002', 2, '桂枝加葛根汤', '10001', '伤寒金匮・(宋版)', '2', '葛根,麻黄,芍药,生姜,甘草,大枣,桂枝', replace(replace(replace('2、$f{桂枝加葛根汤} 7味 @@NL@@$u{葛根}$w{四两}    $u{麻黄}$w{三两。去节}    $u{芍药}$w{二两}    $u{生姜}$w{三两。切}    $u{甘草}$w{二两。炙}    $u{大枣}$w{十二枚。擘}    $u{桂枝}$w{二两。去皮}@@NL@@@@TB@@上七味。以水一斗。先煮麻黄葛根。减二升。去上沫。内诸药。煮取三升。去滓。温服一升。覆取微似汗。不须啜粥。余如桂枝法。将息及禁忌。$a{臣亿等谨按仲景本论。太阳中风自汗用桂枝。伤寒无汗用麻黄。今证云汗出恶风而方中有麻黄。恐非本意也。第三卷有葛根汤证云。无汗恶风。正与此方同。是合用麻黄也。此云桂枝加葛根汤。恐是桂枝中但加葛根耳。}', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 1, '600025451450437', '88198AB7EE560E2891088A3D6F074204', '2024-09-17 08:59:43', '2024-09-17 08:59:43'),
('fy000000003', 3, '桂枝加厚朴杏子汤', '10001', '伤寒金匮・(宋版)', '3', '桂枝,甘草,生姜,芍药,大枣,厚朴,杏仁', replace(replace(replace('3、$f{桂枝加厚朴杏子汤} 7味 @@NL@@$u{桂枝}$w{三两。去皮}    $u{甘草}$w{二两。炙}    $u{生姜}$w{三两。切}    $u{芍药}$w{三两}    $u{大枣}$w{十二枚。擘}    $u{厚朴}$w{二两。炙去皮}    $u{杏仁}$w{五十枚。去皮尖}@@NL@@@@TB@@上七味。以水七升。微火煮取三升。去滓。温服一升。覆取微似汗。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 1, '600025451884613', 'F9236D60A55268E5C46F88FB5AFEB8A4', '2024-09-17 08:59:43', '2024-09-17 08:59:43'),
('fy000000004', 4, '桂枝加附子汤', '10001', '伤寒金匮・(宋版)', '4', '桂枝,芍药,甘草,生姜,大枣,附子', replace(replace(replace('4、$f{桂枝加附子汤} 6味 @@NL@@$u{桂枝}$w{三两。去皮}    $u{芍药}$w{三两}    $u{甘草}$w{三两。炙}    $u{生姜}$w{三两。切}    $u{大枣}$w{十二枚。擘}    $u{附子}$w{一枚。炮去皮破八片}@@NL@@@@TB@@上六味。以水七升。煮取三升。去滓。温服一升。【本云桂枝汤。今加附子。将息如前法。】', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 1, '600025452310597', '02953A141FBB4A5533FC2A6AB3AAB7C1', '2024-09-17 08:59:43', '2024-09-17 08:59:43'),
('fy000000005', 5, '桂枝去芍药汤', '10001', '伤寒金匮・(宋版)', '5', '桂枝,甘草,生姜,大枣', replace(replace(replace('5、$f{桂枝去芍药汤} 4味 @@NL@@$u{桂枝}$w{三两。去皮}    $u{甘草}$w{二两。炙}    $u{生姜}$w{三两。切}    $u{大枣}$w{十二枚。擘}@@NL@@@@TB@@上四味。以水七升。煮取三升。去滓。温服一升。【本云桂枝汤。今去芍药。将息如前法】', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 1, '600025452752965', '696A1ED2B8B6217F3176B1DD7A250DC0', '2024-09-17 08:59:43', '2024-09-17 08:59:43'),
('fy000000006', 6, '桂枝去芍药加附子汤', '10001', '伤寒金匮・(宋版)', '6', '桂枝,甘草,生姜,大枣,附子', replace(replace(replace('6、$f{桂枝去芍药加附子汤} 5味 @@NL@@$u{桂枝}$w{三两。去皮}    $u{甘草}$w{二两。炙}    $u{生姜}$w{三两。切}    $u{大枣}$w{十二枚。擘}    $u{附子}$w{一枚。炮去皮破八片}@@NL@@@@TB@@上五味。以水七升。煮取三升。去滓。温服一升。【本云桂枝汤。今去芍药。加附子。将息如前法。】', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 1, '600025453174853', '3A45B249FE98DC742E1085DAB561D74B', '2024-09-17 08:59:43', '2024-09-17 08:59:43'),
('fy000000007', 7, '桂枝麻黄各半汤', '10001', '伤寒金匮・(宋版)', '7', '桂枝,芍药,生姜,甘草,麻黄,大枣,杏仁', replace(replace(replace('7、$f{桂枝麻黄各半汤} 7味 @@NL@@$u{桂枝}$w{一两十六铢。去皮}    $u{芍药}    $u{生姜}$w{切}    $u{甘草}$w{炙}    $u{麻黄}$w{各一两。去节}    $u{大枣}$w{四枚。擘}    $u{杏仁}$w{二十四枚。汤浸去皮尖及两仁者}@@NL@@@@TB@@上七味。以水五升。先煮麻黄一二沸。去上沫。内诸药。煮取一升八合。去滓。温服六合。【本云桂枝汤三合。麻黄汤三合。并为六合。顿服。将息如上法。】$a{臣亿等谨按桂枝汤方。桂枝芍药生姜各三两。甘草二两。大枣十二枚。麻黄汤方麻黄三两。桂枝二两。甘草一两。杏仁七十个。今以算法约之。二汤各取三分之一。即得桂枝一两十六铢。芍药生姜甘草各一两。大枣四枚。杏仁二十三个。零三分枚之一。收之得二十四个。合方。详此方乃三分之一。非各半也。宜云合半汤。}', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 1, '600025453596741', 'FBDC1B5FAD16EF2421F1B7A67EF21945', '2024-09-17 08:59:43', '2024-09-17 08:59:43'),
('fy000000008', 8, '桂枝二麻黄一汤', '10001', '伤寒金匮・(宋版)', '8', '桂枝,芍药,麻黄,生姜,杏仁,甘草,大枣', replace(replace(replace('8、$f{桂枝二麻黄一汤} 7味 @@NL@@$u{桂枝}$w{一两十七铢。去皮}    $u{芍药}$w{一两六铢}    $u{麻黄}$w{十六铢。去节}    $u{生姜}$w{一两六铢。切}    $u{杏仁}$w{十六个。去皮尖}    $u{甘草}$w{一两二铢。炙}    $u{大枣}$w{五枚。擘}@@NL@@@@TB@@上七味。以水五升。先煮麻黄一二沸。去上沫。内诸药。煮取二升。去滓。温服一升。日再服。【本云桂枝汤二分。麻黄汤一分。合为二升。分再服。今合为一方。将息如前法。】$a{臣亿等谨按桂枝汤方。桂枝芍药生姜各三两。甘草二两大枣十二枚。麻黄汤方。麻黄三两。桂枝二两。甘草一两。杏仁七十个。今以算法约之。桂枝汤取十二分之五。即得桂枝芍药生姜各一两六铢。甘草二十铢。大枣五枚。麻黄汤取九分之二。即得麻黄十六铢。桂枝十铢三分铢之二。收之得十一铢。甘草五铢三分铢之一。收之得六铢。杏仁十五个九分枚之四。收之得十六个。二汤所取相合。即共得桂枝一两十七铢。麻黄十六铢。生姜芍药各一两六铢。甘草一两二铢。大枣五枚。杏仁十六个。合方。}', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '2', 1, '600025454018629', '319C7329BA20C811464776176122CA5A', '2024-09-17 08:59:43', '2024-09-17 08:59:43'),
('fy000000009', 9, '白虎加人参汤', '10001', '伤寒金匮・(宋版)', '9', '知母,石膏,甘草,粳米,人参', replace(replace(replace('9、$f{白虎加人参汤} 5味 @@NL@@$u{知母}$w{六两}    $u{石膏}$w{一斤。碎绵裹}    $u{甘草}$w{炙。二两}    $u{粳米}$w{六合}    $u{人参}$w{三两}@@NL@@@@TB@@上五味。以水一斗。煮米熟汤成。去滓。温服一升。日三服。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 1, '600025454428229', 'AEEF82412A804D5833D28C5DDF1D5289', '2024-09-17 08:59:43', '2024-09-17 08:59:43'),
('fy000000010', 10, '桂枝二越婢一汤', '10001', '伤寒金匮・(宋版)', '10', '桂枝,芍药,麻黄,甘草,大枣,生姜,石膏', replace(replace(replace('10、$f{桂枝二越婢一汤} 7味 @@NL@@$u{桂枝}$w{去皮}    $u{芍药}    $u{麻黄}    $u{甘草}$w{各十八铢。炙}    $u{大枣}$w{四枚。擘}    $u{生姜}$w{一两二铢。切}    $u{石膏}$w{二十四铢。碎绵裹}@@NL@@@@TB@@上七味。以水五升。煮麻黄一二沸。去上沫。内诸药。煮取二升。去滓。温服一升。【本云当裁为越婢汤桂枝汤。合之饮一升。今合为一方。桂枝汤二分。越婢汤一分。】$a{臣亿等谨按桂枝汤方。桂枝芍药生姜各三两。甘草二两。大枣十二枚。越婢汤方麻黄二两。生姜三两。甘草二两。石膏半斤。大枣十五枚。今以算法约之。桂枝汤取四分之一。即得桂枝芍药生姜各十八铢。甘草十二铢。大枣三枚。越婢汤取八分之一。即得麻黄十八铢。生姜九铢。甘草六铢。石膏二十四铢。大枣一枚八分之七。弃之。二汤所取相合。即共得桂枝芍药甘草麻黄各十八铢。生姜一两三铢。石膏二十四铢。大枣四枚。合方。旧云。桂枝三。今取四分之一。即当云桂枝二也。越婢汤方。见仲景杂方中。外台秘要。一云起脾汤。}', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '2', 1, '600025454825541', '2D6D43BF6949C424766F0885B9ABBEBF', '2024-09-17 08:59:43', '2024-09-17 08:59:43'),
