('fy000000118', 5, '麻黄杏仁薏苡甘草汤', '10002', '金匮要略・(宋版)', '118', '麻黄,甘草,薏苡仁,杏仁', replace(replace(replace('5、$f{麻黄杏仁薏苡甘草汤} $m{4味} $u{麻黄}$w{去节，半两，汤泡}，$u{甘草}$w{一两，炙}，$u{薏苡仁}$w{半两}，$u{杏仁}$w{十个，去皮尖，炒}@@NL@@@@TB@@$s{右四味}，剉麻豆大，每服四钱匕，水盏半，煮八分，去滓。温服，有微汗，避风。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 1, '600025539694661', '691316346662F0935C372999BD088556', '2024-09-17 08:59:52', '2024-09-17 08:59:52'),
('fy000000119', 6, '防己黄芪汤', '10002', '金匮要略・(宋版)', '119', '防己,甘草,白术,黄芪,生姜,大枣,麻黄,芍药,桂枝,细辛', replace(replace(replace('6、$f{防己黄芪汤} $m{6味} $u{防己}$w{一两}，$u{甘草}$w{半两，炒}，$u{白术}$w{七钱半}，$u{黄芪}$w{一两一分，去芦}@@NL@@@@TB@@$s{右四味}，剉麻豆大，每抄五钱匕，$u{生姜}$w{四片}，$u{大枣}$w{一枚}，水盏半，煎八分，去滓。温服，良久再服。喘者，加$u{麻黄}$w{半两}；胃中不和者，加$u{芍药}$w{三分}；气上冲者，加$u{桂枝}$w{三分}；下有陈寒者，加$u{细辛}$w{三分}。服后当如虫行皮中，从腰下如冰，后坐被上，又以一被绕腰以下，温，令微汗，差。$q{《外台》}：治风水。脉浮为在表，其人或头汗出，表无他病，病者但下重，从腰以上为和，腰以下当肿及阴，难以屈伸。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 1, '600025540026437', '498227F319FFEA068703A078DAFA06C2', '2024-09-17 08:59:52', '2024-09-17 08:59:52'),
('fy000000120', 7, '桂枝附子汤', '10002', '金匮要略・(宋版)', '120', '桂枝,生姜,附子,甘草,大枣', replace(replace(replace('7、$f{桂枝附子汤} $m{5味} $u{桂枝}$w{四两，去皮}，$u{生姜}$w{三两，切}，$u{附子}$w{三枚，炮，去皮，破八片}，$u{甘草}$w{二两，炙}，$u{大枣}$w{十二枚，擘}@@NL@@@@TB@@$s{右五味}，以水六升，煮取二升，去滓，分温三服。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 1, '600025540440133', '250C2851506C8AAC861D8B6EF5DD500B', '2024-09-17 08:59:52', '2024-09-17 08:59:52'),
('fy000000121', 8, '白术附子汤', '10002', '金匮要略・(宋版)', '121', '白术,附子,甘草,生姜,大枣', replace(replace(replace('8、$f{白术附子汤} $m{5味} $u{白术}$w{二两}，$u{附子}$w{一枚半，炮，去皮}，$u{甘草}$w{一两，炙}，$u{生姜}$w{一两半，切}，$u{大枣}$w{六枚}@@NL@@@@TB@@$s{右五味}，以水三升，煮取一升，去滓，分温三服。一服觉身痹，半日许再服，三服都尽，其人如冒状，勿怪，即是术、附并走皮中逐水气，未得除故耳。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 1, '600025540821061', '7B55B5FD4472097403C807D54D870B11', '2024-09-17 08:59:52', '2024-09-17 08:59:52'),
('fy000000122', 9, '甘草附子汤', '10002', '金匮要略・(宋版)', '122', '甘草,附子,白术,桂枝', replace(replace(replace('9、$f{甘草附子汤} $m{4味} $u{甘草}$w{二两，炙}，$u{附子}$w{二枚，炮，去皮}，$u{白术}$w{二两}，$u{桂枝}$w{四两，去皮}@@NL@@@@TB@@$s{右四味}，以水六升，煮取三升，去滓。温服一升，日三服。初服得微汗则解。能食，汗出复烦者，服五合。恐一升多者，服六七合为妙。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 1, '600025541181509', '624D32B52AE8281E36C0697B59FECF14', '2024-09-17 08:59:52', '2024-09-17 08:59:52'),
('fy000000123', 10, '白虎加人参汤', '10002', '金匮要略・(宋版)', '123', '知母,石膏,甘草,粳米,人参', replace(replace(replace('10、$f{白虎加人参汤} $m{5味} $u{知母}$w{六两}，$u{石膏}$w{一斤，碎}，$u{甘草}$w{二两}，$u{粳米}$w{六合}，$u{人参}$w{三两}@@NL@@@@TB@@$s{右五味}，以水一斗，煮米熟汤成，去滓。温服一升，日三服。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 1, '600025541513285', 'A49D25C7A6C544DFAC1887B15082FD41', '2024-09-17 08:59:52', '2024-09-17 08:59:52'),
('fy000000124', 11, '一物瓜蒂汤', '10002', '金匮要略・(宋版)', '124', '瓜蒂', replace(replace(replace('11、$f{一物瓜蒂汤} $m{1味} $u{瓜蒂}$w{二七个}@@NL@@@@TB@@$s{右剉}，以水一升，煮取五合，去滓，顿服。又治诸黄。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '1', 1, '600025541849157', '236C190459A6CF1E85F7536FA8149358', '2024-09-17 08:59:52', '2024-09-17 08:59:52'),
('fy000000125', 12, '百合知母汤', '10002', '金匮要略・(宋版)', '125', '百合,知母', replace(replace(replace('12、$f{百合知母汤} $m{2味} $u{百合}$w{七枚，擘}，$u{知母}$w{三两，切}@@NL@@@@TB@@$s{右先以水洗百合}，渍一宿，当白沫出，去其水，更以泉水二升，煎取一升，去滓；别以泉水二升煎知母，取一升，去滓；后合和煎，取一升五合。分温再服。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '2', 1, '600025542221893', '5ACF6937AC41FEA5F25876A75CB3AE87', '2024-09-17 08:59:52', '2024-09-17 08:59:52'),
('fy000000126', 13, '滑石代赭汤', '10002', '金匮要略・(宋版)', '126', '百合,滑石,代赭石', replace(replace(replace('13、$f{滑石代赭汤} $m{3味} $u{百合}$w{七枚，擘}，$u{滑石}$w{三两，碎，绵裹}，$u{代赭石}$w{如弹丸大一枚，碎，绵裹}@@NL@@@@TB@@$s{右先以水洗百合}，渍一宿，当白沫出，去其水，更以泉水二升，煎取一升，去滓；别以泉水二升煎滑石、代赭，取一升，去滓；后合和重煎，取一升五合，分温服。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '2', 1, '600025542553669', '519EBDB87627DD10AE1E9570B89EFA80', '2024-09-17 08:59:52', '2024-09-17 08:59:52'),
('fy000000127', 14, '百合鸡子汤', '10002', '金匮要略・(宋版)', '127', '百合,鸡子黄', replace(replace(replace('14、$f{百合鸡子汤} $m{2味} $u{百合}$w{七枚，擘}，$u{鸡子黄}$w{一枚}@@NL@@@@TB@@$s{右先以水洗百合}，渍一宿，当白沫出，去其水，更以泉水二升，煎取一升，去滓，内鸡子黄，搅匀，煎五分，温服。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '1', 1, '600025542881349', 'C3B08FE59461B81DA7131EC64E0ABE7C', '2024-09-17 08:59:53', '2024-09-17 08:59:53'),
('fy000000128', 15, '百合地黄汤', '10002', '金匮要略・(宋版)', '128', '百合,生地黄', replace(replace(replace('15、$f{百合地黄汤} $m{2味} $u{百合}$w{七枚，擘}，$u{生地黄}$w{汁一升}@@NL@@@@TB@@$s{右以水洗百合}，渍一宿，当白沫出，出其水，更以泉水二升，煎取一升，去滓，内地黄汁，煎取一升五合，分温再服。中病，勿更服，大便当如漆。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 1, '600025543233605', '253097BBBA2D265CEC89B0C6DA46E78E', '2024-09-17 08:59:53', '2024-09-17 08:59:53'),
('fy000000129', 16, '百合洗', '10002', '金匮要略・(宋版)', '129', '百合', replace(replace(replace('16、$f{百合洗} $m{1味} $u{百合}$w{一升}@@NL@@@@TB@@$s{右以百合一升}，以水一斗，渍之一宿，以洗身。洗已，食煮饼，勿以盐豉也。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '1', 1, '600025543544901', '72999B0D88C27F271D750BAB49F73BFF', '2024-09-17 08:59:53', '2024-09-17 08:59:53'),
('fy000000130', 17, '栝楼牡蛎散', '10002', '金匮要略・(宋版)', '130', '栝楼根,牡蛎', replace(replace(replace('17、$f{栝楼牡蛎散} $m{2味} $u{栝楼根}，$u{牡蛎}$w{熬，等分}@@NL@@@@TB@@$s{右为细末}，饮服方寸匕，日三服。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '1', 1, '600025543843909', '6A20ED652CAD00002E6B265AF5EFAAB1', '2024-09-17 08:59:53', '2024-09-17 08:59:53'),
('fy000000131', 18, '百合滑石散', '10002', '金匮要略・(宋版)', '131', '百合,滑石', replace(replace(replace('18、$f{百合滑石散} $m{2味} $u{百合}$w{一两，炙}，$u{滑石}$w{三两}@@NL@@@@TB@@$s{右为散}，饮服方寸匕，日三服。当微利者，止服，热则除。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '20', 1, '600025544183877', 'FDC4251305B1D77A768B4A16354C21CF', '2024-09-17 08:59:53', '2024-09-17 08:59:53'),
('fy000000132', 19, '甘草泻心汤', '10002', '金匮要略・(宋版)', '132', '甘草,黄芩,人参,干姜,黄连,大枣,半夏', replace(replace(replace('19、$f{甘草泻心汤} $m{7味} $u{甘草}$w{四两}，$u{黄芩}，$u{人参}，$u{干姜}$w{各三两}，$u{黄连}$w{一两}，$u{大枣}$w{十二枚}，$u{半夏}$w{半斤}@@NL@@@@TB@@$s{右七味}，水一斗，煮取六升，去滓，再煎。温服一升，日三服。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 1, '600025544503365', '6AB68794393C4C31263E8776F86657A8', '2024-09-17 08:59:53', '2024-09-17 08:59:53'),
('fy000000133', 20, '苦参汤', '10002', '金匮要略・(宋版)', '133', '苦参', replace(replace(replace('20、$f{苦参汤} $m{1味} $u{苦参}$w{一升}@@NL@@@@TB@@$s{以水一斗}，煎取七升，去滓，熏洗，日三服。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 1, '600025544855621', '1445A93D67A08FC15B4371AA514F3AAE', '2024-09-17 08:59:53', '2024-09-17 08:59:53'),
('fy000000134', 21, '雄黄', '10002', '金匮要略・(宋版)', '134', '雄黄', replace(replace(replace('21、$f{雄黄} $m{1味} $u{雄黄}@@NL@@@@TB@@$s{右一味为末}，筒瓦二枚合之，烧，向肛熏之。$a{$q{《脉经》}云：病人或从呼吸上蚀其咽，或从下焦蚀其肛阴，蚀上为惑，蚀下为狐，狐惑病者，$f{猪苓散}主之。}', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '1', 1, '600025545216069', 'E24A821F71B800DD0F9C18DD221B57C9', '2024-09-17 08:59:53', '2024-09-17 08:59:53'),
('fy000000135', 22, '赤豆当归散', '10002', '金匮要略・(宋版)', '135', '赤小豆,当归', replace(replace(replace('22、$f{赤豆当归散} $m{2味} $u{赤小豆}$w{三升，浸令芽出，曝干}，$u{当归}$w{三两}@@NL@@@@TB@@$s{右二味}，杵为散，浆水服方寸匕，日三服。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '180', 1, '600025545580613', '9ECD8C49101A9FB36F63EF06229729B8', '2024-09-17 08:59:53', '2024-09-17 08:59:53'),
('fy000000136', 23, '升麻鳖甲汤', '10002', '金匮要略・(宋版)', '136', '升麻,当归,蜀椒,甘草,鳖甲,雄黄', replace(replace(replace('23、$f{升麻鳖甲汤} $m{6味} $u{升麻}$w{二两}，$u{当归}$w{一两}，$u{蜀椒}$w{炒去汗，一两}，$u{甘草}$w{二两}，$u{鳖甲}$w{手指大一片，炙}，$u{雄黄}$w{半两，研}@@NL@@@@TB@@$s{右六味}，以水四升，煮取一升，顿服之。老少再服，取汗。$a{$q{《肘后》}、$q{《千金方》}：阳毒用升麻汤，无鳖甲，有桂；阴毒用甘草汤，无雄黄。}', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '1', 1, '600025545977925', '424252E396E104C7E495F27C19653415', '2024-09-17 08:59:53', '2024-09-17 08:59:53'),
('fy000000137', 24, '鳖甲煎丸', '10002', '金匮要略・(宋版)', '137', '鳖甲,乌扇,黄芩,柴胡,鼠妇,干姜,大黄,芍药,桂枝,葶苈,石苇,厚朴,牡丹,瞿麦,紫葳,半夏,人参,䗪虫,阿胶,蜂窠,赤硝,蜣螂,桃仁,煅灶下灰,清酒', replace(replace(replace('24、$f{鳖甲煎丸} $m{23味} $u{鳖甲}$w{十二分，炙}，$u{乌扇}$w{三分，烧}，$u{黄芩}$w{三分}，$u{柴胡}$w{六分}，$u{鼠妇}$w{三分，熬}，$u{干姜}$w{三分}，$u{大黄}$w{三分}，$u{芍药}$w{五分}，$u{桂枝}$w{三分}，$u{葶苈}$w{一分，熬}，$u{石苇}$w{三分，去毛}，$u{厚朴}$w{三分}，$u{牡丹}$w{五分，去心}，$u{瞿麦}$w{二分}，$u{紫葳}$w{三分}，$u{半夏}$w{一分}，$u{人参}$w{一分}，$u{䗪虫}$w{五分，熬}，$u{阿胶}$w{三分，炙}，$u{蜂窠}$w{四分，熬}，$u{赤硝}$w{十二分}，$u{蜣螂}$w{六分，熬}，$u{桃仁}$w{二分}@@NL@@@@TB@@$s{右二十三味为末}，取$u{煅灶下灰}$w{一斗}，$u{清酒}$w{一斛五斗}，浸灰，候酒尽一半，着鳖甲于中，煮令泛烂如胶漆，绞取汁，内诸药，煎为丸，如梧子大。空心服七丸，日三服。$a{$q{《千金方》}鳖甲片十二片，又有海藻三分，大戟一分，䗪虫五分，无鼠妇、赤硝二味，以鳖甲和诸药为丸。}', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '50', 1, '600025546408005', '97DB38246116AAD0CE9FBA8589E97D4B', '2024-09-17 08:59:53', '2024-09-17 08:59:53'),
('fy000000138', 25, '白虎加桂枝汤', '10002', '金匮要略・(宋版)', '138', '桂枝,粳米,石膏,甘草,知母', replace(replace(replace('25、$f{白虎加桂枝汤} $m{5味} $u{知母}$w{六两}，$u{甘草}$w{二两，炙}，$u{石膏}$w{一斤}，$u{粳米}$w{二合}，$u{桂枝}$w{去皮，三两}@@NL@@@@TB@@$s{右剉}，每五钱，水一盏半，煎至八分，去滓。温服，汗出愈。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '2', 1, '600025546850373', '7A239DBEEC640467B0A53E933783FF0F', '2024-09-17 08:59:53', '2024-09-17 08:59:53'),
('fy000000139', 26, '蜀漆散', '10002', '金匮要略・(宋版)', '139', '蜀漆,云母,龙骨', replace(replace(replace('26、$f{蜀漆散} $m{3味} $u{蜀漆}$w{烧去腥}，$u{云母}$w{烧二日夜}，$u{龙骨}$w{等分}@@NL@@@@TB@@$s{右三味}，杵为散，未发前，以浆水服半钱。温疟加$u{蜀漆}$w{半分}，临发时，服一钱匕。$a{一方云母作云实。}', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '1', 1, '600025547259973', '7F8F806C9F7716625F12A7797C8A0143', '2024-09-17 08:59:53', '2024-09-17 08:59:53'),
('fy000000140', 27, '牡蛎汤', '10002', '金匮要略・(宋版)', '140', '牡蛎,麻黄,甘草,蜀漆', replace(replace(replace('27、$q{附《外台秘要》}$f{牡蛎汤} $m{4味} 治牡疟。@@NL@@@@TB@@$u{牡蛎}$w{四两，熬}，$u{麻黄}$w{四两，去节}，$u{甘草}$w{二两}，$u{蜀漆}$w{三两}@@NL@@@@TB@@$s{右四味}，以水八升，先煮蜀漆、麻黄，去上沫，得六升，内诸药，煮取二升，温服一升。若吐，则勿更服。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '2', 1, '600025547698245', 'E8B227A3A551C49B3EE1CA92B0051CDE', '2024-09-17 08:59:53', '2024-09-17 08:59:53'),
