('fy000000393', 78, '猪苓汤', '9040000', '伤寒论・(人纪)', '393', '猪苓,茯苓,阿胶,滑石,泽泻', replace(replace(replace('$u{猪苓}$w{去皮}，$u{茯苓}，$u{阿胶}，$u{滑石}，$u{泽泻}$w{各一两}@@NL@@@@TB@@$s{右五味}，以水四升，先煮四味，取二升，去滓，内阿胶烊消，温服七合，日三服。  @@NL@@@@NL@@     胖子各三钱，普通人各二钱就可以了，先煮四味，就是把阿胶拿出来，阿胶都是后下的，一天吃三次，中药没有记饭前或饭后服，则一律饭前吃。  @@NL@@@@NL@@  《类聚方广义》本方条曰：治淋病点滴不通，阴头肿痛，少腹膨胀而痛者，若茎中痛，出脓血者，都可以用猪苓汤。  @@NL@@@@NL@@       又：妊妇七八月后，有牝护焮热肿痛，不能起卧，小便淋沥者，以三棱针轻轻刺肿处，放出瘀水后，再用此方，则肿痛立消，小便快利。怀孕中间小便不通，要用到猪苓汤，还有若一身悉肿者，宜越婢加朮汤，怀孕的时候水肿，就是越婢加朮汤，越婢再加白朮，所以孕妇水肿是越婢加朮汤，小便不通是猪苓汤。  @@NL@@@@NL@@      《尊水琐言》曰：满身洪肿，以手力按其肿，放手则按处忽复起胀，肿胀虽如是其甚，然未曾有碍呼吸，气息亦如平日，是猪苓汤证也。更有肿势如前，腰以下虽满肿，臂、肩、胸、背无恙，呼吸仍如寻常者，是亦可用猪苓汤，勿必问其渴之有无。所以下半肿也可以用猪苓汤，水肿的时候，有些水要用发汗发掉，不发汗则喘满，就要用越婢加朮汤。  ', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '616856743944261', '4B9ECA0B220EB48F2096FCD9699673D5', '2024-11-28 11:36:33', '2024-11-28 11:36:33'),
('fy000000394', 79, '蜜煎导', '9040000', '伤寒论・(人纪)', '394', '蜜', replace(replace(replace('$u{蜜}$w{七合}@@NL@@@@TB@@一味。纳铜器中，微火煎之，稍凝似饴状，搅之勿令焦着。欲可丸，并手捻作梃，令头锐，大如指，长二寸许。 当热时急作，冷则硬。以纳谷道中，以手急抱，欲大便时乃去之。 又$u{大猪胆}$w{一枚。泻汁}。和少许$u{醋}。以灌谷道内。如一食顷。当大便出宿食恶物。甚效。@@NL@@@@NL@@       把蜂蜜熬到感觉黏的程度如麦牙糖一样就关火，等稍微温一点的时候，并手捻作梃，令头锐，大如指，长二寸许，用手搓成一条一头大一头尖的，趁温的时候做好，等凉了以后插到肛门去，大头先进，肠子蠕动会让它往里面跑，以手急抱，欲大便时乃去之，用手抱到，有要大便感觉的时候再放手。  ', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '1', 0, '616941846040645', 'DFF381F250AC35F7A5898C7E477635C0', '2024-11-28 17:22:50', '2024-11-28 17:22:50'),
('fy000000395', 80, '土瓜根', '9040000', '伤寒论・(人纪)', '395', NULL, '方缺', '0', 0, '616943151439941', '29B5EC5E93B83D7311CC58263F4B071F', '2024-11-28 17:28:09', '2024-11-28 17:28:09'),
('fy000000396', 81, '大猪胆汁', '9040000', '伤寒论・(人纪)', '396', '猪胆汁', 'u{大猪胆}$w{一枚、泻汁}，和少许$u{法醋}，以灌谷道内，如一食顷，当大便出宿食恶物，甚效。', '1', 0, '616943458758725', '476DEBD521915503D8382A3D5EB4685F', '2024-11-28 17:29:24', '2024-11-28 17:29:24'),
('fy000000397', 82, '茵陈蒿汤', '9040000', '伤寒论・(人纪)', '397', '大黄,栀子,茵陈蒿', replace(replace(replace('$u{茵陈蒿}$w{六两}    $u{栀子}$w{十四枚、擘}    $u{大黄}$w{二两、去皮}@@NL@@@@TB@@ 右三味,以水一斗,先煮茵陈,减六升,纳二味,煮取三升,去滓,分温三服,小便当利,尿如皂角汁,色正赤,一宿腹减,黄从小便去也。 @@NL@@@@NL@@   先煮茵陈蒿，再煮其它两味。茵陈蒿在胖子或刚发病黄很盛的时候，可以开到五六钱，瘦人三钱就够了，栀子的量和茵陈蒿差不多，大黄约茵陈蒿的三分之一即可。 @@NL@@    @@NL@@ 《勿误药室方函口诀》本方条曰：此方为治发黄之圣剂；茵陈蒿专治发黄，盖有解湿热及利水之效。  ', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '617184637898821', '763B2D526F1EA2D44DEE5B7948E884C6', '2024-11-29 09:50:45', '2024-11-29 09:50:45'),
('fy000000398', 83, '吴茱萸汤', '9040000', '伤寒论・(人纪)', '398', '大枣,生姜,人参,吴茱萸', replace(replace(replace('$u{吴茱萸}$w{一升}，$u{人参}$w{三两}，$u{生姜}$w{六两}，$u{大枣}$w{十二枚}@@NL@@@@TB@@$s{右四味}，以水五升，煮取三升。温服七合，日三服。@@NL@@@@NL@@  吴茱萸用三钱，重证的时候可以用到五钱，人参、生姜、大枣酌量的用。@@NL@@@@NL@@《肘后方》曰：一方（即本方）治人食毕噫醋及醋心（即食后吞酸嘈杂也）。  @@NL@@@@NL@@ 张元素曰：吴茱萸汤其用有三：去胸中之逆气满塞，止心腹寒感疼痛，及消宿酒。早上宿醉未醒，可以用吴茱萸汤，吴茱萸汤对酒客病非常的好。@@NL@@', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '617197769121861', '904D92C55A0876E37E26B2B1E6FB6BE5', '2024-11-29 10:44:11', '2024-11-29 10:44:11'),
('fy000000399', 84, '麻仁丸', '9040000', '伤寒论・(人纪)', '399', '麻子仁,芍药,枳实,大黄,厚朴,杏仁', replace(replace(replace('$u{麻子仁}$w{二升}，$u{芍药}$w{半斤}，$u{枳实}$w{半斤、炙}，$u{大黄}$w{一斤}，$u{厚朴}$w{一斤、炙、去皮}，$u{杏仁}$w{一斤、去皮尖，研作脂}@@NL@@@@NL@@    右六味，为末，炼蜜为丸，桐子大。每服十丸，旦三服，渐加，以知为度。  @@NL@@@@NL@@    开处方的时候照比例开，麻子仁二，白芍六，枳实六，大黄十二，厚朴十二，杏仁十二。  @@NL@@@@NL@@     《方函口诀》引闲斋曰：治老人之秘结最佳。然本方虽和缓，究属攻破之剂，尝见有误用致死者。老人血液枯燥而便秘者，得大剂肉苁蓉辄通利；若用本方，虽取快一时，不旋踵而秘结益甚，不可不知。常常看到老年人大便像羊大便一样，一颗一颗的，肉苁蓉是补肾，是男人壮精的药，把精力壮起来，体能恢复以后，肠胃蠕动功能恢复，自然而然把大便排出来。年龄大的人身体很虚，没有体力承受承气汤的威力，所以紧急时可用猪胆汁导法和蜜煎导法，从肛门把大便清出来，  ', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '617203947024453', 'FEC5706F98F6A7DACC596C76A3F10D0A', '2024-11-29 11:09:19', '2024-11-29 11:09:19'),
('fy000000400', 85, '栀子蘗皮汤', '9040000', '伤寒论・(人纪)', '400', '黄柏,甘草,栀子', replace(replace(replace('$u{栀子}$w{十五个、擘}    $u{甘草}$w{一两、炙}    $u{黄柏}$w{二两}@@NL@@@@NL@@右三味，以水四升，煮取一升半，去滓，分温再服  @@NL@@@@NL@@栀子用二、三钱，炙甘草一钱，黄柏二钱，胖子用栀子用到三、五钱没关系，栀子和黄柏的剂量相等，为什么甘草要炙过?因为药下去，要同时能够停在上焦、中焦、下焦，如果炙甘草没炙过，上焦还没清，栀子已经跑到下焦去了，所以用炙甘草在中间的时候，让栀子停在上焦，黄柏清利下焦。  ', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '2', 0, '617214152740933', '4C7C1A9CDF58CBEA9F5B1E9F34966DAA', '2024-11-29 11:50:51', '2024-11-29 11:50:51'),
('fy000000401', 86, '麻黄连轺赤小豆汤', '9040000', '伤寒论・(人纪)', '401', '甘草,生姜,生梓白皮,大枣,赤小豆,杏仁,连轺,麻黄', replace(replace(replace('$u{麻黄}$w{二两。去节}    $u{ 连轺}$w{（连翘）二两}    $u{杏仁}$w{四十个、去皮尖}    $u{赤小豆}$w{一升}    $u{大枣}$w{十二枚、擘}    $u{生梓白皮}$w{一升、切}    $u{生姜}$w{二两、切}    $u{甘草}$w{二两、炙}@@NL@@', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '617216463597637', '05B4222BF24E6ECC7D5AD653BCF448C7', '2024-11-29 12:00:15', '2024-11-29 12:00:15'),
('fy000000402', 87, '桂枝加大黄汤', '9040000', '伤寒论・(人纪)', '402', '大黄,大枣,生姜,芍药,桂枝,甘草', replace(replace(replace('$u{桂枝}$w{三两、去皮}    $u{大黄}$w{一两}    $u{芍药}$w{三两}    $u{甘草}$w{二两、炙}    $u{生姜}$w{三两、切}    $u{大枣}$w{十二枚、擘}@@NL@@右六味,以水七升,煮取三升,去滓,温服一升,日三服。 @@NL@@ 桂枝加大黄汤里面桂枝三钱、芍药三钱,再加大黄,大黄去实。  ', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '617563378458693', '8533F9D50A1E747F2741E0FCBC3EE865', '2024-11-30 11:31:51', '2024-11-30 11:31:51'),
('fy000000403', 88, '桂枝加芍药汤', '9040000', '伤寒论・(人纪)', '403', '桂枝,芍药,甘草,生姜,大枣', replace(replace(replace('$u{桂枝}$w{三两、去皮}    $u{芍药}$w{六两}    $u{甘草}$w{二两、炙}    $u{生姜}$w{三两、切}    $u{大枣}$w{十二枚、擘}@@NL@@@@TB@@右五味,以水七升,煮取三升,去滓,分温三服。 @@NL@@桂枝加芍药汤里面桂枝三钱,芍药六钱', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '617564194377797', '1D6BEE191BBE3EB14F59D38F7CD4FAEE', '2024-11-30 11:35:10', '2024-11-30 11:35:10'),
('fy000000404', 89, '麻黄附子细辛汤', '9040000', '伤寒论・(人纪)', '404', '麻黄,细辛,附子', replace(replace(replace('$u{麻黄}$w{二两、去节}    $u{细辛}$w{二两}    $u{附子}$w{一枚(炮、去皮、破八片)}@@NL@@     右三味，以水一升，先煮麻黄，减二升，去上沫，纳诸药，煮取三升，去滓，温服一升，日三服。@@NL@@     一般处方的时候,麻黄细辛等量,譬如二钱,附子是加重的,三钱或四钱,@@NL@@ 因为附子要配合细辛,又要配合麻黄,一药双用,@@NL@@ 如果附子和细辛等量,附子配细辛,麻黄吃下去,照样没有小便,把附子加重,一部份配合麻黄,一部份配合细辛大黄也是一样的功能,@@NL@@ 因为要通大便,所以把麻黄换大黄,舌苔白的,跳脉一息二下,代表蠕动很慢,这就是寒实。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '617618070921285', '0FD640F7B0CD198EE9B62C0FA645E967', '2024-11-30 15:14:24', '2024-11-30 15:14:24'),
('fy000000405', 90, '大黄附子细辛汤', '9040000', '伤寒论・(人纪)', '405', '大黄,细辛,附子大黄,细辛,附子大黄,细辛,附子,', replace(replace(replace('$u{大黄}$w{二两}    $u{细辛}$w{二两}    $u{附子}$w{一枚(炮、去皮、破八片)}@@NL@@     一般处方的时候,麻黄细辛等量,譬如二钱,附子是加重的,三钱或四钱,@@NL@@ 因为附子要配合细辛,又要配合麻黄,一药双用,@@NL@@ 如果附子和细辛等量,附子配细辛,麻黄吃下去,照样没有小便,把附子加重,一部份配合麻黄,一部份配合细辛大黄也是一样的功能,@@NL@@ 因为要通大便,所以把麻黄换大黄,舌苔白的,跳脉一息二下,代表蠕动很慢,这就是寒实。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '617622123651141', 'E07ED7B94FB9503CE00EC07ABBB8781F', '2024-11-30 15:30:53', '2024-11-30 15:30:53'),
('fy000000406', 91, '麻黄附子甘草汤', '9040000', '伤寒论・(人纪)', '406', '附子,甘草,麻黄', replace(replace(replace('$u{麻黄}$w{二两。去节}    $u{甘草}$w{二两。炙}    $u{附子}$w{一枚(炮。去皮。破八片)}@@NL@@      右三味，以水七升，先煮麻黄一二沸，去上沫，纳诸药，煮取三升，去渣，温服一升，日三服。  @@NL@@@@NL@@      麻黄附子细辛汤和麻黄附子甘草汤的不一样就是细辛和甘草，细辛是升阳，升里阳的，里阳下陷的时候，寒在里面，就是阳升不上来，肾脏下焦的阳应该要往上升，上焦的阳要往下降，才能够交会起来，肾脏的水，到膀胱以后，在胞室，就是精宫，阳火很热很大，把膀胱的水蒸化，蒸化了以后，废水由小便出来，还有部分水，水生木，进入肝胆，然后变成胆汁再分泌出来，这段就是下焦的火，如果这一段的火没了，细辛有这功能让它提升上来。  @@NL@@@@NL@@张仲景的甘草用炙的时候，用在两个地方@@NL@@@@NL@@       一个目的是补他的津液的不足，所以有麻黄附子甘草汤，是少阴病得到二三天以后用的；少阴病，如果刚开始的时候是麻黄附子甘草汤，因为免疫系统要跟滤过性病毒相抗，津液会伤到，所以少阴病得到二三天的以后，津液伤到的时候，用炙甘草下去补他，所以要取他的微发其汗，315条的少阴病，始得之，反发热，这刚开始得到少阴病的时候，津液还没有伤到，就是麻黄附子细辛汤，@@NL@@@@NL@@       第二在经方里面，复脉，凡是脉不正常，心律不整的时候，不管是跳的太快，或怎样，一定会用到炙甘草，炙甘草的力量很强，所以炙甘草汤实际上是让脉恢复正常最有力的方子，所以炙甘草汤，芍药甘草附子汤，麻黄附子甘草汤，都重用炙甘草。  @@NL@@@@NL@@        如果不用炙过的甘草，用一般的生甘草，张仲景的想法是，第一津液不够了，第二肠里还有一些食物腐坏掉了，用甘草去解毒，这就是一般《本草纲目》写的，甘草可以解百毒，实际上像滤过性病毒，毒蛇咬的，吃甘草都不会好的，所谓解百毒，是把肠胃里面坏掉的食物中和掉，好的留为己用，桂枝汤里面用炙甘草不用生甘草的原因是担心发表以后，胃肠中津液丧失，所以做预先防范的动作。  ', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '617624568123461', 'D9E729E65D9B47E0BF8F90F9E12C75A3', '2024-11-30 15:40:50', '2024-11-30 15:40:50'),
('fy000000407', 92, '黄连阿胶汤', '9040000', '伤寒论・(人纪)', '407', '鸡子黄,阿胶,芍药,黄芩,黄连', replace(replace(replace('$u{黄连}$w{四两}    $u{黄芩}$w{二两}    $u{芍药}$w{二两}    $u{鸡子黄}$w{二枚}    $u{阿胶}$w{三两}@@NL@@ 右五味，以水五升，先煮三物，取二升，去渣，内胶烊尽，小冷，纳鸡子黄，搅令相得，温服七合，日三服。  @@NL@@@@NL@@        先煮三物，就是黄连、黄芩、芍药先煮，五碗水煮成二碗，去渣，再用小微火，阿胶放进，让阿胶化掉后。把火关掉，等它冷了后，纳鸡子黄，搅令相得，不要汤很烫的时候放鸡子黄，那会变成蛋花汤，这地方鸡蛋要生用，叫鸡子黄就是生用，鸡子黄是补心血，鸡蛋生用和熟用不一样，所以小冷，也不要太冷，因此粉剂就没用了。  @@NL@@@@NL@@      《类聚方广义》本方条曰：诸失血证，胸悸，身热，腹痛微利，舌干唇燥，烦悸不能寐，身体困惑，面无血色，或面热潮红者均效。@@NL@@@@NL@@      临床上，黄连阿胶汤大部分用在手术以后的烦躁，因为很虚没有办法入眠，年龄大的人，气血两虚的状况下，没有办法入眠，这时候用安眠药没有用，灸三毛稍微睡一下，或睡得不是很深，可以用黄连阿胶汤下去当安眠剂。 ', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '617631504343109', 'B2929B09368778BA2F2DC7EDD252F0B3', '2024-11-30 16:09:04', '2024-11-30 16:09:04'),
('fy000000408', 93, '附子汤', '9040000', '伤寒论・(人纪)', '408', '芍药,白术,茯苓,人参,附子', replace(replace(replace('$u{附子}$w{二枚(炮、去皮、破八片)}    $u{茯苓}$w{三两}    $u{人参}$w{二两}    $u{白术}$w{四两}    $u{芍药}$w{三两}@@NL@@@@NL@@   右五味，以水八升，煮取三升，去渣，温服一升，日二服。  @@NL@@@@NL@@     这附子汤里面如果把人参换成生姜，就是真武汤，真武汤的时候，白朮和茯苓的剂量不一样，附子汤里面，白朮如果是四，茯苓就是三，白朮比茯苓重，所以重在健脾上面，真武汤里面茯苓重用，白朮比较少，因为真武汤是小便不利，所以真武汤是水结下焦，这水在走的时候要靠生姜，附子把胃里面的水排掉，因为生姜能散水，然后茯苓把水利出去，所以把人参拿掉。  @@NL@@@@NL@@     虚寒疼痛，全身骨节疼痛的时候用附子汤。  ', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '2', 0, '617633713471557', '67EA2ED9E4CE851B1D65B4B37C2DAFEC', '2024-11-30 16:18:03', '2024-11-30 16:18:03'),
('fy000000409', 94, '桃花汤', '9040000', '伤寒论・(人纪)', '409', '粳米,干姜,赤石脂', replace(replace(replace('$u{赤石脂}$w{一斤，一半全用，一半筛末}，$u{干姜}$w{一两}，$u{粳米}$w{一升}@@NL@@@@TB@@$s{右三味}，以水七升，煮米令熟，去渣，温服七合，纳赤石脂末，方寸匕，日三服，若愈，余勿服。  @@NL@@@@NL@@      赤石脂胖子用五钱，因为里寒所以用干姜，干姜温中，为什么不用人参?因为人参是补津液的。用人参时，肠里面的病毒会不出来，所以用糯米，能生津就好了，不要把它固住，粳米放一勺就好了，不要煮成糯米饭，赤石脂一半打碎生用，一半跟着药一起煮，汤煮好了再放赤石脂的粉末，赤石脂生用就是要把药整个固涩在胃里，让肠子固住，不再下利，消炎的力量很强，一剂下去就不再下利了。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '617635145957445', '8A20F15C7AEA36C15BFAD8629F89D104', '2024-11-30 16:23:53', '2024-11-30 16:23:53'),
('fy000000410', 95, '猪肤汤', '9040000', '伤寒论・(人纪)', '410', '猪肤', replace(replace(replace('$u{猪肤}$w{一斤}    $u{白蜜}、$u{白粉}$w{(即大米粉)}@@NL@@  右一味，以水一斗，煮取五升，去渣，加$u{白蜜}$w{一升}    $u{白粉}$w{五合}，熬香，和令相得，温分六服。  @@NL@@@@NL@@      单味的药去煮，加蜂蜜，再加白粉，就是米粉。猪皮加白蜜，都是能增补我们的胰液，米粉能助胃消化，米已经打碎成粉了，如果再不能消化，此人就差不多了，加蜂蜜就是健脾胃，甜的入脾，脾包含了胰。  @@NL@@@@NL@@      像少阴证会有下利，咽痛，心烦的现象，就是阴虚掉了，里面功能没有了，肺里热往上跑，跑到上面来就是喉咙痛，跑到下面就是下利，但是又不象桃花汤全部在下面，又不象黄连阿胶汤全部在上面，病毒分开来的，所以并没有便脓血，因为热往两边跑，所以用猪肤汤主之。  @@NL@@  ', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '6', 0, '617637558530117', '94DE0994E7772858B5C1B6873EC6A0A0', '2024-11-30 16:33:42', '2024-11-30 16:33:42'),
('fy000000411', 96, '甘草汤', '9040000', '伤寒论・(人纪)', '411', '甘草', replace(replace(replace('$u{甘草}$w{二两}@@NL@@@@NL@@右一味，以水三升，煮取一升半，去渣，温服七合，日一服。  @@NL@@@@NL@@如果单味药，开一两二两没有关系，甘草二，桔梗一。  @@NL@@@@NL@@      为什么喉咙痛会伴随着痰饮?因为喉咙是肺的开口，也是胃的开口，所以喉咙和气管和食道都结在一起。如果喉咙痛就是肿起来了，肿起来气行就不是很顺畅，很多热气就慢慢囤积在这里，如果热堵到了，就会生很多黏液，就会造成痰，有痰的时候靠桔梗，桔梗汤能宣肺化痰，@@NL@@      金匮里面只有两个排脓汤方，其一就是甘草桔梗汤，所以这脓肯定是肺里面化脓，肺里面痰太多了；@@NL@@              第二当归赤小豆散，用来治痔疮化脓；另外是薏苡附子败酱散，这汤方是已经转化成腹膜炎，盲肠炎，大黄牡丹皮汤来不及煮，转成腹膜炎的时候用的。  ', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '617639444516933', '897A219B82E098C489A619811DACA894', '2024-11-30 16:41:22', '2024-11-30 16:41:22'),
('fy000000412', 97, '桔梗汤', '9040000', '伤寒论・(人纪)', '412', '桔梗,甘草', replace(replace(replace('$u{桔梗}$w{一两}    $u{甘草}$w{二两}@@NL@@@@TB@@右二味、以水三升、煮取一升、去滓、温分再服。@@NL@@@@NL@@    甘草二，桔梗一。  @@NL@@    为什么喉咙痛会伴随着痰饮?因为喉咙是肺的开口，也是胃的开口，所以喉咙和气管和食道都结在一起。如果喉咙痛就是肿起来了，肿起来气行就不是很顺畅，很多热气就慢慢囤积在这里，如果热堵到了，就会生很多黏液，就会造成痰，有痰的时候靠桔梗，桔梗汤能宣肺化痰，金匮里面只有两个排脓汤方，其一就是甘草桔梗汤，所以这脓肯定是肺里面化脓，肺里面痰太多了；第二当归赤小豆散，用来治痔疮化脓；另外是薏苡附子败酱散，这汤方是已经转化成腹膜炎，盲肠炎，大黄牡丹皮汤来不及煮，转成腹膜炎的时候用的。  ', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '2', 0, '617640823869509', '7AB400797C16373B2AF6423671544FFE', '2024-11-30 16:46:59', '2024-11-30 16:46:59'),
('fy000000413', 98, '苦酒汤', '9040000', '伤寒论・(人纪)', '413', '鸡子,半夏', replace(replace(replace('$u{半夏}$w{十四枚(洗、破如枣核)}    $u{鸡子}$w{一枚、去黄} 内上 $u{苦酒}$w{着鸡子壳中}@@NL@@    右二味，内半夏，著苦酒中，以鸡子壳，置刀环中，安火上，令三沸，去滓，少少含咽之，不差，更作三剂。  @@NL@@@@NL@@          半夏用生半夏，拿一颗两颗，严重的拿二颗，熟半夏没有用，洗生半夏的时候把生半夏戳破，鸡子就是鸡蛋，用铁架子架着蛋壳，在火面上烧，蛋壳里面留一点蛋白，再倒些苦酒汤在里面，然后生半夏放进去，用打火机在下面烧，烧的时候要看，看蛋壳中蛋清表面起一二个泡泡出来就关火，不要煮太熟，滚一二下，先喝一口，慢慢的喝下去，很冲的，喉咙开了就好了，针灸的时候，在扁桃腺上放血，还有过去有医生用巴豆与贝母做成巴豆霜，把巴豆霜用管子吹到喉咙上去，巴豆不要用吃的，用吃的舌头会破个洞，结果喉咙还是没好，临床上，喉咙都闭到了，吞不下东西的时候，像木舌证，也是用这苦酒来让喉咙打开，含在嘴巴里面，没有吞下去没关系，针灸的话，在舌头下方的金津玉液放血。  @@NL@@@@NL@@    《金鉴》曰：半夏涤涎，蛋清敛疮，苦酒消肿，则咽清而生出矣。用半夏来去痰，蛋清来收敛疮，利用蛋清的润滑收他的疮，因为苦酒汤攻下去的时候，喉咙会破掉，所以火不能太热，太热就变成蛋白了，苦酒来消肿。 ', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '1', 0, '617642419077189', '919EE17F46516245D8CB6409578A2EAA', '2024-11-30 16:53:28', '2024-11-30 16:53:28'),
('fy000000414', 99, '半夏散及汤', '9040000', '伤寒论・(人纪)', '414', '甘草,桂枝,半夏', replace(replace(replace('$u{半夏}$w{(洗)}    $u{桂枝}$w{去皮}    $u{甘草}$w{炙}   以上各等分  @@NL@@ 以上三味，各别捣筛已，合治之，白饮和，服方寸匕，日三服，若不能散服者，以水一升，煎七沸，内散两方寸匕，更煎三沸，下火令小冷，少少咽之。  @@NL@@@@NL@@      这就是少阴证的喉痛，少阴证的时候本身又有中风，本来少阴证得到了一段时间，津液本来就不足了，因为里面阴虚很盛，没有办法有正常的津液给喉咙，这时候用桂枝来去风，用甘草、半夏，这就是有少阴证的同时得到有表证的时候用的，就是带有伤寒感冒的时候用的，这三味等分，白饮就是米汤，不能服散用汤剂也可以。  @@NL@@@@NL@@      《勿误药室方函口诀》本方条曰：此方宜于冬时中寒，咽喉疼痛者，虽有发热、恶寒、可治。然此证冬时为多。又后世所谓火喉癣证，上焦有虚热，而喉头烂，痛苦不堪，饮食不能下咽，用甘桔汤及其它诸治喉痛药无寸效者，用之一旦而有效；临证上，严重到吞不下去了用苦酒汤，如果本身是少阴证还兼有伤寒的表证，所以摸脉很重要，少阴证的人脉很虚弱，就是这人里虚了，里虚就是肠胃功能没有吸收，病人很虚弱，这时候得到的喉咙痛，一定是虚火，不是实火，实火用黄连、黄芩等消炎的药，虚火就不能用。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '1', 0, '617643459616837', 'EA0FD3DFC0574CFA11B6DA3D7D072BBC', '2024-11-30 16:57:42', '2024-11-30 16:57:42'),
('fy000000415', 100, '白通汤', '9040000', '伤寒论・(人纪)', '415', '葱白,附子,干姜', replace(replace(replace('$u{葱白}$w{四茎}    $u{干姜}$w{一两}    $u{附子}$w{一枚(生。去皮。破八片)}@@NL@@右三味，以水三升，煮取一升，去滓，分温再服。  @@NL@@@@NL@@       白通汤用葱白、干姜、附子，附子生用，用生附的时候，一定是和干姜并用的，炮附一定是和生姜并用，生附和干姜能温经散寒，力量能达到表上面去，从神经血脉一直到四肢末稍，炮附和生姜能去里寒，尤其是中焦、下焦里面的寒水，所以生姜有利水的功能，炮附能去寒，所以现在白通汤的目的就是要温经散寒。  @@NL@@@@NL@@    少阴病，下利，少阴病的人会下利就是里虚掉了，什么时机用白通汤?  @@NL@@@@NL@@    第一四逆汤，会用到四逆汤一定是手脚冰冷了，可是四逆汤的主证，是肠胃里面的热能没有办法达到四肢，简单讲就是中阳不振，中焦的阳，脾胃的功能不好，或味口不好，舌苔白白的，里寒很盛，脾胃没有热度，所以造成手脚冰冷的就是用四逆汤。  @@NL@@@@NL@@    第二附子汤，附子汤在用的时候，表里皆寒且虚，连阳都不足了，所以附子汤可以补阳的不足，如果是表寒里虚，阳气很足的时候都是小青龙汤证。  @@NL@@@@NL@@     第三就是白汤通，是阴盛在下，虚阳在上，白通汤的目的是让上下通达，所以少阴证下利的时候，因为里寒太盛了，上焦的胸阳、心阳没有办法往下走，结果下焦的阳不足，上面的阳下不来，变成上面是热，下面是寒，下面的肠胃没有蠕动，东西就坏死掉，造成不断的下利，这时候就要用白通汤。  @@NL@@@@NL@@     白通汤里面的葱白，只用葱的白茎，和干姜、附子一起煮，因为没有炙甘草，所以药一下去的时候，没有阻碍，一下去就能把上焦的阳往下带，干姜来温中，生附能行到表面上，能把肠胃的蠕动加速，让血行到四肢上去。  @@NL@@@@NL@@      通脉四逆汤，就是阴盛于内，阳隔于外，摸病人微发热，可是舌苔伸出来全部是白的，就是表热里寒，如果前面是太阳证的话，要开解表的药，也要开去里寒的药，如果少阴证的时候，就不一样，少阴证的表热是假像的热，病人的体能快被阴赶出去了，所以脉已经很微细了，很危险了，这时候要开通脉四逆汤，能打通他全身的血脉，所以通脉就是通达内外。通脉四逆汤和四逆汤的区别，病人的脉都是微细的，但是四逆汤只胃阳虚而已，所以四逆汤  @@NL@@的病人手脚冰冷，通脉四逆汤的病人手脚热的，但是脉都快没了。  @@NL@@@@NL@@所以上下不能通的时候用白通汤，全身都虚寒的时候靠附子汤，内外阴阳不能协和的时候用通脉四逆汤。  @@NL@@', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '2', 0, '617645865730117', 'D1A3F093184C1ACC6E7988D3DD82917D', '2024-11-30 17:07:30', '2024-11-30 17:07:30'),
('fy000000416', 101, '白通加猪胆汁汤', '9040000', '伤寒论・(人纪)', '416', '猪胆汁,附子,干姜,葱', replace(replace(replace('$u{葱白}$w{四茎}    $u{干姜}$w{一两}    $u{附子}$w{一枚(生、去皮、破八片)}   $u{猪胆汁}$w{一合}@@NL@@右三味，以水三升，煮取一升，去滓，纳胆汁、   $u{人尿}$w{五合}  ，和令相得，分温再服，若无胆亦可用。  ', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '2', 0, '617649430237253', 'A73AE6FC60D70E4359C960EA1396A87C', '2024-11-30 17:22:00', '2024-11-30 17:22:00'),
('fy000000417', 102, '真武汤', '9040000', '伤寒论・(人纪)', '417', '干姜,细辛,五味子,附子,白术,芍药,生姜,茯苓', replace(replace(replace('$u{茯苓}    $u{芍药}    $u{生姜}$w{各三两、切}    $u{白术}$w{二两}    $u{附子}$w{一枚(炮、去皮、破八片)}@@NL@@@@TB@@右五味，以水八升，煮取三升，去滓，温服七合，日三服。 @@NL@@@@NL@@真武汤方加减法  @@NL@@@@NL@@      若咳者。加$u{五味子}$w{半升}    $u{细辛}$w{一两}    $u{干姜}$w{一两}。@@NL@@      若小便利者。去$u{茯苓}。@@NL@@      若下利者。去$u{芍药}。加$u{干姜}$w{二两}。@@NL@@      若呕者。去$u{附子}。加$u{生姜}。$w{足前为半斤。}@@NL@@@@NL@@      张仲景常常在咳嗽的时候加细辛、五味子，加干姜，代表这是水饮的咳，水气往上冲的时候，所以加细辛、五味子，下来再遇到干姜，水气就去掉了。如果小便很正常，茯苓就不用了。张仲景在寒利的时候一定会用干姜，所以如果下利很重，加干姜。呕吐的很厉害，代表水饮很重，胃里面有一定的水，过量的时候就会恶心，所以靠生姜，生姜能散胃里面的水，胃的蠕动不好的时候要靠干姜，所以生姜、干姜不一样。  @@NL@@', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '4', 0, '617651411988549', '76AB3F87BA99A445027F3C4CA2577258', '2024-11-30 17:30:04', '2024-11-30 17:30:04'),
('fy000000418', 103, '通脉四逆汤', '9040000', '伤寒论・(人纪)', '418', '附子,甘草,干姜', replace(replace(replace(' $u{附子}$w{大者一枚，生用}，$u{干姜}$w{三两，强人可四两}，$u{甘草}$w{二两，炙}@@NL@@@@TB@@$s{右三味}，以水三升，煮取一升二合，去滓，分温再服，其脉即渐出者愈。@@NL@@ @@NL@@     非若暴出者之自无而忽有，既有而仍无，如灯火之回焰也。@@NL@@@@NL@@     面赤色者，加葱九茎。@@NL@@     腹中痛者，去葱，加芍药二两。@@NL@@     呕者，加生姜二两。@@NL@@     若咽痛者，去芍药，加桔梗一两。@@NL@@     利止，脉不出者，去桔梗，加人参二两。  @@NL@@@@NL@@       以水三碗煮一碗，若暴出者之自无而忽有，既有而仍无，有时候有，有时候又没有，如灯火之回焰也，面赤色者加葱九茎，这时候通脉四逆汤加葱茎，因为上下相隔，应急的时候，可以通脉四逆汤加白通汤，腹中痛者，这代表肠里面的血停滞，这时候要靠白芍，白芍一下去把血带到肝里面，肝静脉的血再回到心脏再换血；若咽痛者，去芍药，加桔梗一两，喉咙痛的加桔梗；利止，脉不出者，去桔梗，加人参二两，为什么最后加人参?如果病人的胃气能恢复，病人就还有救。  @@NL@@', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '2', 0, '618265699557445', '699F29B1167BC97D5A3E42687A0E88E5', '2024-12-02 11:09:36', '2024-12-02 11:09:36'),
('fy000000419', 104, '四逆散', '9040000', '伤寒论・(人纪)', '419', '柴胡,芍药,枳实,甘草', replace(replace(replace('$u{甘草}$w{炙}    $u{枳实}$w{(破、水渍、炙干)}    $u{芍药}    $u{柴胡}@@NL@@@@TB@@右四味，各十分，捣筛，白饮合服方寸匕，日三服。@@NL@@@@NL@@     咳者。加$u{五味子}、$u{干姜}$w{各五分}。并主下利。@@NL@@     悸者。加$u{桂枝}$w{五分}。@@NL@@     小便不利者。加$u{茯苓}$w{五分}。@@NL@@     腹中痛者。加$u{附子}$w{一枚、炮令坼}。@@NL@@     泄利下重者。先以水五升。煮$u{薤白}$w{三升}、去滓、以散三方寸匕、内汤中、煮取一升半、分温再服。@@NL@@@@NL@@       薤白这药，本身能开肺，肺气一开的时候下就通了，因为肺和大肠相表里的，所以有的人便秘吃承气汤没有用，实际上是肺气没有打开来，思能伤脾，忧能伤肺，常担心的人相会改变。眉毛下方会看到白色的，眉底的肉会变成白色的，所以肺病的人可以看到白色，眉毛和肺有关系，眉毛只剩几根的空壳子，外表穿的很华丽，相书里面看眉毛很稀落的人，代表这人里面一无所有，所以掉眉毛和掉头发不一样，头发主肾，所以如果能让忧虑去掉，让肺开开来，就能让眉毛长回来，眉毛很长的代表长寿，所以要保持平常心。  @@NL@@@@NL@@      如果是肌肉里面血堵到了，被打伤，肌肉里面淤血的时候用桂枝汤加桃仁，如果是打到内部、肠胃的地方、三焦网络的内伤，就用四逆散来作加减。 @@NL@@ ', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '618270700793925', '6E04E75517303D04E34ADA7A120F2ACC', '2024-12-02 11:29:57', '2024-12-02 11:29:57');
INSERT OR IGNORE INTO fang_yao (id, fang_no, fang_name, source_book_legacy_id, source_book_name,  source_fang_legacy_id, yao_list, fang_text, fang_drink_num, is_enable,  signature_id, signature, created_at, updated_at) VALUES
('fy000000420', 105, '乌梅丸', '9040000', '伤寒论・(人纪)', '420', '黄柏,人参,桂枝,蜀椒,附子,当归,黄连,干姜,细辛,乌梅', replace(replace(replace('$u{乌梅}$w{三百个}，$u{细辛}$w{六两}，$u{干姜}$w{十两}，$u{黄连}$w{一斤}，$u{当归}$w{四两}，$u{附子}$w{六两，炮}，$u{蜀椒}$w{四两、炒去汁}，$u{桂枝}$w{六两}，$u{人参}$w{六两}，$u{黄柏}$w{六两}@@NL@@@@TB@@$s{右十味}，异捣筛，合治之，以$u{苦酒}渍乌梅一宿，去核，蒸之五升米下，饭熟，捣成泥，和药令相得，内臼中，与$u{蜜}杵二千下，丸如梧子大。先食，饮服十丸，三服，稍加至二十丸。禁生冷滑臭等食。@@NL@@@@NL@@       乌梅先泡醋泡一个晚上，再用米去蒸，蒸熟后把米跟乌梅捣在一起，和蜜，细辛辣是很辣的，干姜也会辣，蜀椒是专门杀菌的，就是巴椒，蜀椒开口无毒闭口有毒、蜀椒、细辛、干姜都是辛辣的，黄连、黄柏是苦的攻下，炮附、桂枝、干姜是热的，让肠胃热起来，把肠胃的环境改变了，虫才不会生在里面，病人有虫在里面，一定是肠胃虚寒的，所以这时候一定吃人参，把肠胃的虚寒补回来，张仲景在肠胃虚寒的时候一定加人参，本身就已是吸收不好，而食物进去胃里面应该吸收化生成血，结果被虫吃掉了，所以用当归把血再补回去。  @@NL@@@@NL@@吃乌梅丸的时候，禁生冷、滑物、臭食等，因为肠胃已经不好了，再吃这些会又再造虫出来，先食饮，服十丸，就是饭前吃乌梅丸，如果饭后吃乌梅丸，人吃到的是乌梅丸，虫吃到的是饭，所以先后顺序对了，虫下来后，肠胃的环境改变了，肠胃变热了，虫就不能呆在里面了。  @@NL@@@@NL@@        乌梅也主久利，这久利指的是寒利。有时候寒到利有带脓血的时候，脓就是炎，这时候用黄连，黄柏、干姜、细辛、炮附就是在寒利的时候用的。中焦过湿无法化除时、也可用此丸剂，其丸苦温，故能去结实之湿。有些病人一紧张就下利，例如遇到考试的时候就下利，也是乌梅丸证。  @@NL@@', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '30', 0, '618318809968709', '0D2957D23E59EA5F9B965C4140F28CBA', '2024-12-02 14:45:43', '2024-12-02 14:45:43'),
('fy000000421', 106, '当归四逆汤', '9040000', '伤寒论・(人纪)', '421', '大枣,通草,甘草,细辛,芍药,桂枝,当归', replace(replace(replace('$u{当归}$w{三两}    $u{桂枝}$w{三两}    $u{芍药}$w{三两}    $u{细辛}$w{三两}    $u{甘草}$w{二两、炙}    $u{通草}$w{二两}    $u{大枣}$w{二十五枚、擘}@@NL@@@@TB@@右七味，以水八升，煮取三升，去滓。温服一升，日三服。  @@NL@@@@NL@@     如果遇到病人很危险的时候，就照上面的剂量开，用两计，平常用钱计，晚上睡觉脚冰冷的，就是当归四逆汤证。还有一个地方用当归四逆汤，就是疝气，疝气时可加上升麻来升提阳气。所以只有疝气和冻疮用到当归四逆汤，还有就是急救的时候用。  @@NL@@@@NL@@       若其人内有久寒者，宜当归四逆加吴茱萸生姜汤主之。  @@NL@@@@NL@@        这内有久寒，讲的是胃寒，在厥阴篇里面讲的，实际上是肝太寒了，引起的胃的功能不正常，所以用当归四逆加吴茱萸生姜汤主之、吴茱萸是最好止呕的圣剂，寒就是有水，所以加生姜把水排掉。  @@NL@@@@NL@@     当归四逆加吴茱萸生姜汤方  @@NL@@@@NL@@  当归三两   桂枝三两   芍药三两   细辛三两   通草二两   甘草二两炙  @@NL@@@@NL@@  吴茱萸二升 生姜半斤   大枣二十五枚  @@NL@@@@NL@@ 右九味，以水六升，清酒六升，和煮取五升，去滓，分温五服。  @@NL@@@@NL@@大部分妇人的带下，就是白带，都是阴寒的体质，这种状况就是当归四逆加吴茱萸生姜汤，人的生殖系统，只有肝经络过。所以当归四逆加吴茱萸生姜汤把肝热起来，白带就去掉了，因此在妇科的时候会用到这方子。  ', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '618343414198341', '8CECD3F8A678C77A80B3F5225F7C97FB', '2024-12-02 16:25:50', '2024-12-02 16:25:50'),
('fy000000422', 107, '当归四逆加吴茱萸生姜汤', '9040000', '伤寒论・(人纪)', '422', '当归,桂枝,芍药,细辛,甘草,通草,生姜,吴茱萸,大枣', replace(replace(replace('$u{当归}$w{三两}    $u{桂枝}$w{三两}    $u{芍药}$w{三两}    $u{细辛}$w{三两}    $u{甘草}$w{二两。炙}    $u{通草}$w{二两}    $u{大枣}$w{二十五枚、擘}    $u{生姜}$w{半斤}    $u{吴茱萸}$w{二升}@@NL@@@@TB@@上九味，以水六升、$u{清酒}$w{六升}和。煮取五升，去滓，温分五服。@@NL@@@@NL@@       大部分妇人的带下，就是白带，都是阴寒的体质，这种状况就是当归四逆加吴茱萸生姜汤，人的生殖系统，只有肝经络过。所以当归四逆加吴茱萸生姜汤把肝热起来，白带就去掉了，因此在妇科的时候会用到这方子。  ', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '5', 0, '618346069364805', '4687DC0D48F25BD3F6C6D4312DD32EF3', '2024-12-02 16:36:38', '2024-12-02 16:36:38'),
('fy000000423', 108, '麻黄升麻汤', '9040000', '伤寒论・(人纪)', '423', '干姜,白术,石膏,甘草,茯苓,桂枝,天门冬,芍药,葳蕤,黄芩,知母,当归,升麻,麻黄', replace(replace(replace('$u{麻黄}$w{二两半、去节}    $u{升麻}$w{一两一分}    $u{当归}$w{一两一分}    $u{知母}$w{十八铢}    $u{黄芩}$w{十八铢}    $u{葳蕤}$w{十八铢}    $u{芍药}$w{六铢}    $u{天门冬}$w{六铢(去心)}    $u{桂枝}$w{六铢}    $u{茯苓}$w{六铢}    $u{甘草}$w{六铢、炙}    $u{石膏}$w{六铢(碎、绵裹)}    $u{白术}$w{六铢}    $u{干姜}$w{六铢}@@NL@@@@TB@@右十四味，以水一斗，先煮麻黄一二沸，去上沫，内诸药，煮取三升，去滓，分温三服，相去如炊三斗米顷令尽，汗出愈。  @@NL@@@@NL@@所以麻黄升麻汤是寒热错杂的处方，由此可见寒热的药可以同时并用。寒热药并用的时候一定要热药冷服，药冷了后再吃。  @@NL@@@@NL@@本方之主证：为表证无汗，兼咽喉溃烂而肠中虚寒下利者。  @@NL@@', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '618353548480581', 'A4ABB41539D8D35F932E7F448B80DF61', '2024-12-02 17:07:04', '2024-12-02 17:07:04'),
('fy000000424', 109, '干姜黄连黄芩人参汤', '9040000', '伤寒论・(人纪)', '424', '干姜,黄芩,黄连,人参', replace(replace(replace('$u{干姜}    $u{黄芩}    $u{黄连}    $u{人参}$w{各三两}@@NL@@@@TB@@右四味、以水六升、煮取二升、去滓、分温再服。@@NL@@四味药等量，各开三钱，干姜温胃寒，黄连、黄芩清肠热，吐、利以后，津液伤到了，一定加人参。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '618354878419013', '828C4FC97F37FC1A75F11771D3B86558', '2024-12-02 17:12:29', '2024-12-02 17:12:29'),
('fy000000425', 110, '白头翁汤治', '9040000', '伤寒论・(人纪)', '425', '秦皮,黄连,黄柏,白头翁', replace(replace(replace('$u{白头翁}$w{二两}    $u{黄柏}$w{三两}    $u{黄连}$w{三两}    $u{秦皮}$w{三两}@@NL@@@@TB@@右四味，以水七升，煮取二升，去滓，温服一升，不愈，更服一升。  @@NL@@@@NL@@      白头翁二钱，白头翁本身有止腹痛，同时能去热，如果光是止腹痛，白芍也可以止腹痛，但是这里是热利，痢疾的原虫把肠子都破坏掉了，肠子里面出血很多，所以靠白头翁和秦皮，秦皮在《本草》写药性苦寒、止涩的功能，味是苦的性是寒的，秦皮有止下利的功能，黄连、黄柏就是清热的药，拉的很厉害的时候，白头翁用五钱都可以。  ', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '2', 0, '618359129698373', '5B7DEFA9EC59B97C32C513955E49F2AA', '2024-12-02 17:29:46', '2024-12-02 17:29:46'),
('fy000000426', 1, '麻黄汤', '1001000', '伤寒杂病论・(桂林古本)', '426', '杏仁,甘草,桂枝,麻黄', replace(replace(replace('$u{麻黄}$w{三两、去节}    $u{桂枝}$w{二两、去皮}    $u{甘草}$w{一两、炙}    $u{杏仁}$w{七十个、去皮尖}@@NL@@@@TB@@右四味，以水九升，先煮麻黄减二升，去上沫，纳诸药，煮取二升半，去滓，温服八合，覆取微似汗，不须粥饮，余如桂枝法将息，桂枝汤见后卷。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '620047195783237', 'FD1E1E7F35375BF7BF5401957354DFD5', '2024-12-07 11:58:32', '2024-12-07 11:58:32'),
('fy000000427', 2, '白虎汤', '1001000', '伤寒杂病论・(桂林古本)', '427', '知母,石膏,甘草,粳米', replace(replace(replace('$u{知母}$w{六两}    $u{石膏}$w{一斤、碎}    $u{甘草}$w{二两、炙}    $u{粳米}$w{六合}@@NL@@@@NL@@     右四味，以水一斗，煮米熟，汤成去滓，温服一升，日三服。@@NL@@', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '620073246429253', '141F96F0587011722688C5E7B7FD42D9', '2024-12-07 13:44:32', '2024-12-07 13:44:32'),
('fy000000428', 3, '大承气汤', '1001000', '伤寒杂病论・(桂林古本)', '428', '大黄,厚朴,枳实,芒硝', replace(replace(replace('$u{大黄}$w{四两、 (酒洗)}    $u{厚朴}$w{半斤 (炙去皮)}    $u{枳实}$w{五枚、(炙)}    $u{芒硝}$w{三合}@@NL@@@@NL@@@@TB@@右四味，以水一斗，先煮二物，取五升，去滓，纳大黄，更煮取二升，去滓，纳芒硝，更上微火一两沸，分温再服，得下余勿服。@@NL@@', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '2', 0, '620076255526981', '721EB01EA09AF359EE5A0C3269397BBF', '2024-12-07 13:56:47', '2024-12-07 13:56:47'),
('fy000000429', 4, '小承气汤', '1001000', '伤寒杂病论・(桂林古本)', '429', '大黄,厚朴,枳实', replace(replace(replace('$u{大黄}$w{四两、(酒洗)}    $u{厚朴}$w{二两、(炙去皮)}    $u{枳实}$w{三枚 (炙)}@@NL@@@@NL@@         右三味，以水四升，煮取一升二合，去滓分温再服，$m{初服更衣者，停后服，不尔者，尽饮之。}', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '2', 0, '620080646508613', '85FB0353D3EEDFB40CC9358AC8187DBA', '2024-12-07 14:14:39', '2024-12-07 14:14:39'),
