('fy000000474', 49, '桂枝麻黄各半汤', '1001000', '伤寒杂病论・(桂林古本)', '474', NULL, '即$f{桂枝汤}三合，$f{麻黄汤}三合，并为六合，顿服之，将息如$f{桂枝汤}法。', '1', 0, '620724466520133', 'FABF2E91C1847911235804DD1492B482', '2024-12-09 09:54:21', '2024-12-09 09:54:21'),
('fy000000475', 50, '桂枝汤', '1001000', '伤寒杂病论・(桂林古本)', '475', NULL, replace(replace(replace('$u{桂枝}$w{三两（去皮） }，$u{芍药}$w{三两 }，$u{甘草}$w{二两（炙） }，$u{生姜}$w{三两（切） }，$u{大枣}$w{十二枚（劈）}@@NL@@@@NL@@        右五味，〖口父〗咀。以水七升，微火煮取三升，去滓，适寒温，服一升。服已须臾，啜热稀粥一升余，以助药力，温覆令一时许，遍身漐漐，微似有汗者益佳，不可令如水流漓，病必不除。若一服汗出病差，停后服，不必尽剂；若不汗，更服依前法；又不汗，后服小促其间，半日许，令三服尽；若病重者，一日一夜服，周时观之。服一剂尽，病证犹在者，更作服；若汗不出，乃服至二三剂。禁生冷、粘滑、肉面、五辛、酒酪、臭恶等物。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '620725110902853', 'A3EB77D41496ADFE46600E4699D2797D', '2024-12-09 09:56:59', '2024-12-09 09:56:59'),
('fy000000476', 51, '大青龙汤', '1001000', '伤寒杂病论・(桂林古本)', '476', NULL, replace(replace(replace('$u{麻黄}$w{六两（去节） }、$u{桂枝}$w{二两（去皮） }、$u{甘草}$w{二两（炙） }、$u{杏仁}$w{四十枚（去皮尖） }、$u{生姜}$w{三两（切） }、$u{大枣}$w{十二枚（劈） }、$u{石膏}$w{如鸡子大（碎） }。@@NL@@@@NL@@      右七味，以水九升，先煮麻黄，减二升，去上沫，纳诸药，煮取三升，去滓，温服一升，取微似汗，汗多者，温粉粉之。一服汗出停后服。若复服汗多亡阳，遂虚，恶风烦躁，不得眠也。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '620725403078725', '9F6F79881CF96014A7895780D7288A75', '2024-12-09 09:58:10', '2024-12-09 09:58:10'),
