('fy000000755', 111, '小青龙汤', '9040000', '伤寒论・(人纪)', '755', NULL, replace(replace(replace('21、$f{小青龙汤} 8味 @@NL@@$u{麻黄}$w{去节}    $u{芍药}    $u{细辛}    $u{干姜}    $u{甘草}$w{炙}    $u{桂枝}$w{各三两。去皮}    $u{五味子}$w{半升}    $u{半夏}$w{半升(洗)}@@NL@@@@TB@@上八味。以水一斗。先煮麻黄。减二升。去上沫。内诸药。煮取三升。去滓。温服一升。若渴。去$u{半夏}。加$u{栝楼根}$w{三两}。若微利。去$u{麻黄}。加$u{荛花}。$w{如一鸡子。熬令赤色}。若噎者。去$u{麻黄}。加$u{附子}$w{一枚。炮}。若小便不利。少腹满者。去$u{麻黄}。加$u{茯苓}$w{四两}。若喘。去$u{麻黄}。加$u{杏仁}$w{半升。去皮尖。}【且荛花不治利。麻黄主喘。今此语反之。疑非仲景意。】$a{臣亿等谨按小青龙汤。大要治水。又按本草荛花下十二水。若水去。利则止也。又按千金。形肿者应内麻黄。乃内杏仁者。以麻黄发其阳故也。以此证之。岂非仲景意也。}', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '643808106459205', '6F31A5C30F3CE21754F96B150C83A308', '2025-02-12 15:21:56', '2025-02-12 15:21:56'),
('fy000000756', 1, '四逆加人参汤', '9050000', '金匮要略・(人纪)', '756', NULL, replace(replace(replace('$u{甘草}$w{二两 (炙)}、$u{附子}$w{一枚 (生用去皮破八片)}、$u{干姜}$w{一两半}、$u{人参}$w{三两}。@@NL@@@@NL@@       右四味，以水三升，煮取一升二合，去滓，分温再服。@@NL@@@@NL@@四逆汤内加人参一两，余依四逆汤服法（上三味，呚咀，微火煮取一升二合，去滓，分温再服。强人可大附子一枚，干姜三两。）  ', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '2', 0, '648718903623749', '8DADD61C2DAC28126D632076D4174711', '2025-02-26 12:24:01', '2025-02-26 12:24:01'),
('fy000000758', 2, '理中丸', '9050000', '金匮要略・(人纪)', '758', NULL, replace(replace(replace('$u{人参}    $u{干姜}    $u{甘草}$w{炙}    $u{白术}$w{各三两}@@NL@@@@NL@@    上四味，捣筛为末，蜜和为丸，如鸡子黄大，以沸汤数合，和一丸研碎，温服之。日三四服，夜一服，腹中未热，益至三四丸，然不及汤，汤法以四物依两数切，用水八升，煮取三升，去渣，温服一升，日三服，@@NL@@@@NL@@     若脐上筑者，肾气动也，去术加桂四两。@@NL@@@@NL@@     吐多者，去术 加生姜三两。@@NL@@@@NL@@     下多者，还用术。@@NL@@@@NL@@     悸者，加茯苓二两。@@NL@@@@NL@@      渴欲得水者，加术，足前成四两半。@@NL@@@@NL@@       腹中痛者，加人参，足前成四两半。@@NL@@@@NL@@       寒者，加干姜，足前成四两半。@@NL@@@@NL@@       腹满者，去术加附子一枚。@@NL@@@@NL@@    服汤后如食顷，饮热粥一升许，微自温，勿揭衣被。  ', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '648720643379269', 'B42863415C94EAD94ECFA2A21B548CE1', '2025-02-26 12:31:05', '2025-02-26 12:31:05'),
('fy000000761', 3, '通脉四逆加猪胆汁汤', '9050000', '金匮要略・(人纪)', '761', NULL, replace(replace(replace('$u{甘草}$w{二两、炙}    $u{干姜}$w{一两半}    $u{附子}$w{一枚、生用去皮破八片}  $u{猪胆汁}$w{半合}@@NL@@@@NL@@    上四味，以水三升，煮取一升二合，去滓，内猪胆汁，分温再服，其脉即来，无猪胆，以羊胆代之。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '2', 0, '648751619280965', '272687F3655A5FDC2E98C1B488B36377', '2025-02-26 14:37:08', '2025-02-26 14:37:08'),
