('fy000000775', 15, '栝蒌牡蛎散', '9050000', '金匮要略・(人纪)', '775', NULL, replace(replace(replace('$u{括蒌根}、$u{牡蛎 (熬) }$w{各等分}。@@NL@@@@NL@@            右二味，捣为散，白饮和服方寸匙，日三服。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '651536493879365', '4E0A20C6D9EE350C9530491D32E45646', '2025-03-06 11:28:49', '2025-03-06 11:28:49'),
('fy000000776', 16, '百合滑石散', '9050000', '金匮要略・(人纪)', '776', NULL, replace(replace(replace('$u{百合}$w{一两 (炙)}、$u{滑石}$w{二两}。@@NL@@@@NL@@        右二味，为散，饮服方寸匙，日三服，当微利，热除则止后服。@@NL@@@@NL@@     百合用炙过，就是用火烧过，或是在锅子里面干炒过。 比例是用百合一两，滑石就要用三两，将这两味药捣成散剂来服。『方 寸匕』就是一个汤匙而已，一天吃三次。如果吃了百合滑石散后有点 下利时就可以停药，因为表示药到了。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '651537176817733', '8119B5ECEF1BD748A8A2AB6844BC30FB', '2025-03-06 11:31:36', '2025-03-06 11:31:36'),
