('fy000000779', 19, '升麻鳖甲汤', '9050000', '金匮要略・(人纪)', '779', NULL, replace(replace(replace('$u{升麻}$w{二两}、$u{蜀椒}$w{一两 (炒去汗)}、$u{雄黄}$w{半两 (研)}、$u{当归}$w{二两}、$u{甘草}$w{二两}、$u{鳖甲}$w{手指大一片 (炙)}。@@NL@@@@NL@@       上六味，以水四升，煮取一升，顿服之，老小再服，取汗。肘后千金方阳毒用升麻汤， 无鳖甲有桂；阴毒用甘草汤，无雄黄。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '2', 0, '651573206970437', '355CB3937E43AEE8FEDF63D5DC0DB33B', '2025-03-06 13:58:12', '2025-03-06 13:58:12'),
('fy000000780', 20, '升麻鳖甲汤去雄黄蜀椒', '9050000', '金匮要略・(人纪)', '780', NULL, replace(replace(replace('$u{升麻}$w{二两}、$u{当归}$w{二两}、$u{甘草}$w{二两}、$u{鳖甲}$w{手指大一片 (炙)}。@@NL@@@@NL@@       上四味，以水四升，煮取一升，顿服之，老小再服，取汗。肘后千金方阳毒用升麻汤， 无鳖甲有桂；阴毒用甘草汤，无雄黄。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '2', 0, '651573606805573', 'E4DA3C0A57E1FEE4590CF3FDA8F8B996', '2025-03-06 13:59:50', '2025-03-06 13:59:50'),
('fy000000781', 21, '鳖甲煎丸', '9050000', '金匮要略・(人纪)', '781', NULL, replace(replace(replace('$u{鳖甲}$w{十二分，炙}，$u{乌扇}$w{三分，烧、即 射干}，$u{黄芩}$w{三分}，$u{柴胡}$w{六分}，$u{鼠妇}$w{三分，熬}，$u{干姜}$w{三分}，$u{大黄}$w{三分}，$u{桂枝}$w{三分}，$u{石苇}$w{三分，去毛}，$u{厚朴}$w{三分}，$u{紫葳}$w{三分 即凌霄 }，$u{半夏}$w{三分}，$u{阿胶}$w{三分，炙}，$u{葶苈}$w{一分，熬}，$u{人参}$w{一分}，$u{瞿麦}$w{二分}，$u{䗪虫}$w{五分，熬}，$u{牡丹}$w{五分，去心}，$u{芍药}$w{五分}，$u{蜂窠}$w{四分，熬}，$u{赤硝}$w{十二分}，$u{蜣螂}$w{六分，熬}，$u{桃仁}$w{二分，去皮尖， 研}@@NL@@@@TB@@$s{上二十三味为末}，取$u{煅灶下灰}$w{一斗}，$u{清酒}$w{一斛五斗}，浸灰，候酒尽一半，着鳖甲于中，煮令泛烂如胶漆，绞取汁，内诸药，煎为丸，如梧子大。空心服七丸，日三服。$a{$q{《千金方》}鳖甲片十二片，又有海藻三分，大戟一分，䗪虫五分，无鼠妇、赤硝二味，以鳖甲和诸药为丸。}', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '50', 0, '651618373013573', '2C939A2551B2DD7CE827A48AB7E4A4E3', '2025-03-06 17:01:59', '2025-03-06 17:01:59'),
('fy000000782', 22, '白虎加桂枝汤', '9050000', '金匮要略・(人纪)', '782', NULL, replace(replace(replace('$u{知母}$w{六两}、$u{石膏}$w{一斤}、$u{甘草}$w{二两(炙)}、$u{粳米}$w{二合}、$u{桂枝}$w{三两}@@NL@@@@NL@@         上五味，以水一斗，煮米熟，汤成去滓，温服一升，日三服。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '651623642656837', '881F312100F19668687B995204BDBD75', '2025-03-06 17:23:25', '2025-03-06 17:23:25'),
('fy000000783', 23, '蜀漆散', '9050000', '金匮要略・(人纪)', '783', NULL, replace(replace(replace('$u{蜀漆}$w{烧去腥}，$u{云母}$w{烧二日夜}，$u{龙骨}$w{等分}@@NL@@@@NL@@@@TB@@$s{上三味}，杵为散，未发前，以浆水服半钱。温疟加$u{蜀漆}$w{半分}，临发时，服一钱匕。$a{一方云母作云实。}', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '1', 0, '651624546123845', '0A5167A32A9CD60B9499185AFFF80BB6', '2025-03-06 17:27:06', '2025-03-06 17:27:06'),
('fy000000784', 24, '牡蛎汤', '9050000', '金匮要略・(人纪)', '784', NULL, replace(replace(replace('$u{牡蛎}$w{四两，熬}，$u{麻黄}$w{四两，去节}，$u{甘草}$w{二两}，$u{蜀漆}$w{三两}@@NL@@@@NL@@上四味，以水八升，先煮蜀漆、麻黄，去上沫，得六升，内诸药，煮取二升，温服一升。若吐，则勿更服。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '2', 0, '651867859562565', '558B52584C2861814E94C164DCB486C9', '2025-03-07 09:57:09', '2025-03-07 09:57:09'),
('fy000000785', 25, '柴胡去半夏加栝蒌汤', '9050000', '金匮要略・(人纪)', '785', NULL, replace(replace(replace('$u{柴胡}$w{八两}，$u{人参}，$u{黄芩}，$u{甘草}$w{各三两}，$u{栝蒌根}$w{四两}，$u{生姜}$w{二两}，$u{大枣}$w{十二枚}@@NL@@@@NL@@@@TB@@上七味，以水一斗二升，煮取六升，去滓，再煎取三升。温服一升，日二服。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '651868227633221', '0D8DFAC3BB7E03A5C2F77A279D9879EB', '2025-03-07 09:58:39', '2025-03-07 09:58:39'),
('fy000000786', 26, '柴胡桂姜汤', '9050000', '金匮要略・(人纪)', '786', NULL, replace(replace(replace('$u{柴胡}$w{半斤}、$u{桂枝}$w{三两、去皮}、$u{干姜}$w{二两}、$u{括蒌根}$w{四两}、$u{黄芩}$w{三两}、$u{甘草}$w{三两(炙)}、$u{牡蛎}$w{三两(熬)}。@@NL@@@@NL@@           上七味，以水一斗，煮取六升，去滓，再煎取三升，温服一升，日三服，初服微烦，再服，汗出便愈。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '651868923334725', 'F819C887C0E10979654DDB6940258E0F', '2025-03-07 10:01:28', '2025-03-07 10:01:28'),
('fy000000787', 27, '防己地黄汤', '9050000', '金匮要略・(人纪)', '787', NULL, replace(replace(replace('$u{防己}$w{一分}，$u{桂枝}$w{三分}，$u{防风}$w{三分}，$u{甘草}$w{一分}。@@NL@@@@TB@@$s{上四味}，以$u{酒}$w{一杯}，渍之一宿，绞取汁。$u{生地黄}$w{二斤}，㕮咀，蒸之如斗米饭久，以铜器盛其汁，更绞地黄汁，和分再服。@@NL@@@@NL@@      防己、甘草、桂枝、防风这些药的比例，防己、甘 草是一，桂枝是三。你不要开一分、三分，这种轻剂量治疗牙齿中风可以用，治疗中风的人需要大剂的药，使用三钱五钱一剂都不为过， 比例要知道。同时像防己本身能够去湿，中气不足的时候用甘草。桂枝和甘草补中，都能够补中阳不足，让脾脏开始运化。防己和防风， 都能够去风。这处方是遇到病人的风邪直接进在皮表，停在经上面的 时候使用的，是最浅的处方。这四味药先用酒泡过，泡完以后再绞它的汁用，汁里面就有药跟酒在里面。生地黄，也要大剂的用，剂量用两，差不多用到二两到三两才够量。@@NL@@@@NL@@        遇到体格比较大的病人，使用四两以上都没关系。地黄生的时候是黏答答的、黑黑的，你把它放在锅里蒸熟，好像蒸米一样，隔水蒸， 不要浸水。蒸熟了以后把它拿起来绞汁。把生地黄绞成生地黄汁，然后跟刚刚前面已经绞成汁的四味药，混合在一起，喝下这个汁，才是 真正的防己地黄汤。地黄汁必须是绞汁的，把它蒸熟的，不是煮熟的， 利用地黄来补病家的血不足。靠桂枝甘草来健中，来加强病人的肠胃功能，然后开一点防己防风去风。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '2', 0, '651946043437125', '5FA2FB11F92BC73B78A5F25E0331F5D7', '2025-03-07 15:15:17', '2025-03-07 15:15:17'),
('fy000000788', 28, '侯氏黑散', '9050000', '金匮要略・(人纪)', '788', NULL, replace(replace(replace('$u{菊花}$w{四十分}，$u{白术}$w{十分}，$u{细辛}$w{三分}，$u{茯苓}$w{三分}，$u{牡蛎}$w{三分}，$u{桔梗}$w{八分}，$u{防风}$w{十分}，$u{人参}$w{三分}，$u{矾石}$w{三分}，$u{黄芩}$w{五分}，$u{当归}$w{三分}，$u{干姜}$w{三分}，$u{芎䓖}$w{三分}，$u{桂枝}$w{三分}。@@NL@@@@NL@@@@TB@@$s{上十四味}，杵为散，$u{酒}服方寸匕，日一服。初服二十日，温酒调服，禁一切鱼、肉、大蒜，常宜冷食，六十日止，即药积在腹中不下也，热食即下矣，冷食自能助药力。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '60', 0, '651948909150277', '35987453D09C152AA7EAEA4E96253915', '2025-03-07 15:26:56', '2025-03-07 15:26:56'),
('fy000000789', 29, '风引汤', '9050000', '金匮要略・(人纪)', '789', NULL, replace(replace(replace('$u{大黄}，$u{干姜}，$u{龙骨}$w{各四两}，$u{桂枝}$w{三两}，$u{甘草}，$u{牡蛎}$w{各二两}，$u{寒水石}，$u{滑石}，$u{赤石脂}，$u{白石脂}，$u{紫石英}，$u{石膏}$w{各六两}。@@NL@@@@TB@@$s{上十二味}，杵，粗筛，以韦囊盛之。取三指撮，井花水三升，煮三沸，温服一升。$a{治大人风引，少小惊痫瘈疭，日数十发，医所不能疗，除热方。巢氏云：脚气宜风引汤。}', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '60', 0, '651949439926341', '7D65FBB49D61C11525DD74AFF45F0A82', '2025-03-07 15:29:06', '2025-03-07 15:29:06'),
('fy000000790', 30, '头风摩散方', '9050000', '金匮要略・(人纪)', '790', NULL, replace(replace(replace('$u{大附子}$w{一枚，炮}，$u{盐}$w{等分}@@NL@@@@TB@@$s{上二味}，为散，沐了，以方寸匕，摩疾上，令药力行。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '10', 0, '651950541905989', '532CE38F052E0AD9DFD173C20FD1B334', '2025-03-07 15:33:35', '2025-03-07 15:33:35'),
('fy000000791', 31, '桂枝芍药知母汤', '9050000', '金匮要略・(人纪)', '791', NULL, replace(replace(replace('$u{桂枝}$w{四两}，$u{芍药}$w{三两}，$u{甘草}$w{二两}，$u{麻黄}$w{二两}，$u{生姜}$w{五两}，$u{白术}$w{四两,炮}，$u{知母}$w{四两}，$u{防风}$w{四两}，$u{附子}$w{二枚，炮}@@NL@@@@TB@@$s{右九味}，以水七升，煮取二升，温服七合，日三服。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '652213851217989', '06524ACAF59A0FEBA58517F7CBF98CF6', '2025-03-08 09:24:59', '2025-03-08 09:24:59'),
('fy000000792', 32, '乌头汤', '9050000', '金匮要略・(人纪)', '792', NULL, replace(replace(replace('$m{5味} 治脚气疼痛，不可屈伸。@@NL@@@@TB@@$u{麻黄}，$u{芍药}，$u{黄芪}$w{各三两}，$u{甘草}$w{三两，炙}，$u{川乌}$w{五枚，㕮咀，以$u{蜜}二升，煎取一升，即出乌头}@@NL@@@@NL@@@@TB@@$s{上五味}，㕮咀四味，以水三升，煮取一升，去滓，内$u{蜜}煎中，更煎之。服七合，不知，尽服之。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '652217539424325', '5C68E48A8AE56BBDBE0BC6F9A652E680', '2025-03-08 09:40:00', '2025-03-08 09:40:00'),
('fy000000793', 33, '矾石汤', '9050000', '金匮要略・(人纪)', '793', NULL, replace(replace(replace('$u{矾石}$w{二两}@@NL@@@@TB@@$s{上一味}，以浆水一斗五升，煎三、五沸，浸脚良。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '1', 0, '652220010750021', 'BFC82AD7BC8EB76528BA032AC3C34299', '2025-03-08 09:50:03', '2025-03-08 09:50:03'),
('fy000000794', 34, '黄耆桂枝五物汤', '9050000', '金匮要略・(人纪)', '794', NULL, replace(replace(replace('$u{黄耆}$w{三两}、$u{桂枝}$w{三两}、$u{芍药}$w{三两}、$u{生姜}$w{六两}、$u{大枣}$w{十二枚}。@@NL@@@@NL@@       上五味，以水六升，煮取二升，温服七合，日三服。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '652329439670341', 'F8782050CA5FBA8EB342C55E6658BE3B', '2025-03-08 17:15:19', '2025-03-08 17:15:19'),
('fy000000795', 35, '桂枝龙骨牡蛎汤', '9050000', '金匮要略・(人纪)', '795', NULL, replace(replace(replace('$u{桂枝}$w{三两}、$u{芍药}$w{三两}、$u{甘草}$w{二两（炙）}、$u{生姜}$w{三两}、$u{大枣}$w{十二枚}、$u{龙骨}$w{三两}、$u{牡蛎}$w{三两}。@@NL@@@@NL@@        右七味，以水七升，煮取三升，去滓，分温三服。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '653030748602437', 'EB05549927B8150B8D46EC927D770A95', '2025-03-10 16:48:57', '2025-03-10 16:48:57'),
('fy000000796', 36, '天雄散', '9050000', '金匮要略・(人纪)', '796', NULL, replace(replace(replace('$u{天雄}$w{三两（炮）}、$u{白术}$w{八两}、$u{桂枝}$w{六两}、$u{龙骨}$w{三两}。@@NL@@@@NL@@        右四味，杵为散，酒服半钱匙，日三服，不知稍增，以知为度。@@NL@@@@NL@@     天雄散是治疗阳虚的，不是治阴虚。阳虚就是代表身体里面阴寒很盛，这时是看不到热症的，如果是阴虚的话，就可以看到热症，但是看到的是虚热。如果病人是失精家，再遇到这种表里都寒的时候， 就是要用天雄散的时机。@@NL@@@@NL@@      天雄的意思就是吃下去天天都雄壮威武，故名叫天雄，天雄药力比附子强很多，附子是三年收成，而它是五年才 收成。你到药房去买天雄，药房会告诉你天雄就是附子，一定会得到 这个答案的。按照神农本草经，三年、四年、五年都不一样，第五年 采收才是天雄。@@NL@@@@NL@@      天雄散就是用散剂，『天雄三两炮』如果散剂的话我 们可以用这个比例，三两就三两没有关系，白术八两、桂枝六两、龙骨三两。经方里面写的是龙骨，但实际用的是牡蛎，牡蛎可能比龙骨还更恰当一点。如果你将龙骨牡蛎都放进去用，也没有关系，原文上 有一点失去方义，其实是可以用牡蛎的。@@NL@@@@NL@@      将这四味药杵为散，用酒服， 半个汤匙，『半钱匕』就是我们平常喝汤的汤匙平匙量。一天吃三次， 饭前空腹吃。吃完了以后，如果没感觉到改变，就是还有亡血失精， 这个时候就要增加剂量。@@NL@@@@NL@@       这个药在经方里面，是属于很强的补阳药， 主治症状还包含阳不举，如果服了天雄散后仍然不举，表示天雄散没 有用了，此时我们就需要用到像阳起石，肉蓰蓉等，还可以再加一些 鹿茸，这几味都是我们中药里面一般的壮阳的药。但是如果你光吃这 种药，结果就是全身汗毛都举起来了，就是那个地方不举，所以要靠 一些药把它带到它该去的地方。@@NL@@@@NL@@       你如果将这壮阳复方放在天雄散里面一起吃，效果就非常的好，还可以放到桂枝龙骨牡蛎汤里面也可以。 这类药千万不要单味的用，要用复方，它才会进入到我们肾脏去。这 几个药都是等量的比例在用的，也可以把鹿茸拿去泡酒，然后一边喝鹿茸酒，一边服天雄散也可以，这些都是中药里面比较强的壮阳药， 一般是阳虚时才会用到。@@NL@@@@NL@@        如果阳没有虚而是阴虚，吃这类壮阳药，就会越吃越热，反而没有用。阴虚的话，病人一定会看到阳亢的症状， 所谓阳亢就是上焦热下面是寒的，也是属于失精家。@@NL@@@@NL@@        阳虚和阴虚治法 不一样，阳虚是看不到阳症，只看到阴症，比如你问病人说会不会口 渴？病人回答说不渴时，就是阳虚了。如果是阴虚，就会很渴，因为 上面的阳热是虚热，所以只要问病人口渴不渴大概就晓得了。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '653312933322821', '16A5E643C03AA6BDF8E37EA44E644D16', '2025-03-11 11:57:10', '2025-03-11 11:57:10'),
('fy000000797', 37, '黄耆建中汤', '9050000', '金匮要略・(人纪)', '797', NULL, replace(replace(replace('$u{桂枝}$w{三两}、$u{芍药}$w{六两}、$u{甘草}$w{二两 (炙)}、$u{生姜}$w{三两（切）}、$u{大枣}$w{十二枚（劈）}、$u{胶饴}$w{一升}、$u{黄芪}$w{一两半}。@@NL@@@@NL@@      右七味，以水七升，煮取三升，去滓，内胶饴，更上微火消解，温服一升，日三服。@@NL@@@@NL@@     气短，胸满者，加生姜一两；@@NL@@     腹满者，去大枣，加茯苓一两半；@@NL@@     大便秘结者，去大枣，加枳实一两半；@@NL@@    疗肺虚 损不足 ，补气加半夏三两。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '653640521424965', '623D6D76EDB3112AC29CE4D07729615C', '2025-03-12 10:10:07', '2025-03-12 10:10:07'),
('fy000000798', 38, '八味肾气丸', '9050000', '金匮要略・(人纪)', '798', NULL, replace(replace(replace('$u{干地黄}$w{八两}、$u{山药}$w{四两}、$u{山茱萸}$w{四两}、$u{泽泻}$w{三两}、$u{牡丹皮}$w{三两}、$u{茯苓}$w{三两}、$u{桂枝}$w{一两}、$u{附子}$w{一枚 (炮)}。@@NL@@@@NL@@          上八味，末之，炼蜜和丸，如梧子大，$n{酒}下十五丸，渐加至二十五丸，日再服，白饮下亦可。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '15', 0, '653655193079877', '0236C53491F846F7619AD76C5FD95C63', '2025-03-12 11:09:49', '2025-03-12 11:09:49'),
('fy000000799', 39, '薯蓣丸', '9050000', '金匮要略・(人纪)', '799', NULL, replace(replace(replace('$u{薯蓣}$w{三十分}，$u{人参}$w{七分}，$u{白术}$w{六分}，$u{茯苓}$w{五分}，$u{甘草}$w{二十八分}，$u{当归}$w{十分}，$u{干地黄}$w{十分}，$u{芍药}$w{六分}，@@NL@@$u{芎藭}$w{六分}，$u{麦门冬}$w{六分}，$u{阿胶}$w{七分}，$u{干姜}$w{三分}，$u{大枣}$w{百枚为膏}，$u{桔梗}$w{五分}，$u{杏仁}$w{六分}，$u{桂枝}$w{十分}，@@NL@@$u{防风}$w{六分}，$u{神曲}$w{十分}，$u{豆黄}$w{卷十分}，$u{柴胡}$w{五分}，$u{白蔹}$w{二分}@@NL@@@@NL@@@@TB@@$s{上二十一味}，末之，炼$u{蜜}和丸，如弹子大。空腹$u{酒}服一丸，一百丸为剂。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '100', 0, '653662088769605', 'E142E2110BF0035C3F083753B9A23CD9', '2025-03-12 11:37:53', '2025-03-12 11:37:53'),
('fy000000800', 40, '酸枣仁汤', '9050000', '金匮要略・(人纪)', '800', NULL, replace(replace(replace('$u{酸枣仁}$w{二升}，$u{甘草}$w{一两}，$u{知母}$w{二两}，$u{茯苓}$w{二两}，$u{芎䓖}$w{二两} @@NL@@@@NL@@@@TB@@$s{上五味}，以水八升，煮酸枣仁，得六升，内诸药，煮取三升，分温三服。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '653662668976197', '3FA775994AACE76F0AD13CB292B54A7F', '2025-03-12 11:40:15', '2025-03-12 11:40:15'),
('fy000000801', 41, '灸甘草汤', '9050000', '金匮要略・(人纪)', '801', NULL, replace(replace(replace('  $u{甘草}$w{四两，炙}，$u{桂枝}，$u{生姜}$w{各三两}，$u{麦门冬}$w{半升}，$u{麻仁}$w{半升}，$u{人参}，$u{阿胶}$w{各二两}，@@NL@@$u{大枣}$w{三十枚}，$u{生地黄}$w{一斤}@@NL@@@@NL@@上九味，以酒七升，水八升，先煮八味，取三升，去滓，内胶消尽，温服一升， 日三服。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '653677728792645', '41ED8E60F940E889254C61BB093F9072', '2025-03-12 12:41:31', '2025-03-12 12:41:31'),
('fy000000802', 42, '獭肝散', '9050000', '金匮要略・(人纪)', '802', NULL, replace(replace(replace('《肘后》獭肝散@@NL@@@@NL@@@@TB@@      獭肝一具@@TB@@@@TB@@@@NL@@@@NL@@炙干末之，水服方寸匕， 日三服。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '653678365655109', '3035BC9492D6FB0A0136B860C1CCA204', '2025-03-12 12:44:07', '2025-03-12 12:44:07'),
('fy000000803', 43, '射干麻黄汤', '9050000', '金匮要略・(人纪)', '803', NULL, replace(replace(replace(' $u{射干}$w{三两}，$u{麻黄}$w{四两}，$u{生姜}$w{四两}，$u{细辛}，$u{紫菀}，$u{款冬花}$w{各三两}，$u{五味子}$w{半升}，$u{大枣}$w{七枚}，$u{半夏}$w{半升}@@NL@@@@TB@@$s{上九味}，以水一斗二升，先煮麻黄两沸，去上沫，内诸药，煮取三升，分温三服。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '3', 0, '653748042600517', 'AB53F408B38E9A047A27D4ACA2BD3A60', '2025-03-12 17:27:38', '2025-03-12 17:27:38'),
('fy000000804', 44, '皂荚丸', '9050000', '金匮要略・(人纪)', '804', NULL, replace(replace(replace('$u{皂荚}$w{八两，刮去皮，用酥炙}@@NL@@@@TB@@$s{上一味}，末之，$u{蜜}丸梧子大。以枣膏和汤服三丸，日三、夜一服。', '@@NL@@', char(10)), '@@TB@@', char(9)), '@@CR@@', char(13)), '4', 0, '654079119441989', 'D6FF1410A007DC669C2BBC1A7B9FCCAC', '2025-03-13 15:54:47', '2025-03-13 15:54:47'),
